import{d as K,C as o,o as L,c as M,a3 as t,E as a,j as e,a as i,k as J}from"./chunks/framework.Q4yG9rk_.js";const W=JSON.parse('{"title":"庄子·徐无鬼","description":"从徐无鬼见魏武侯、相狗相马与真人之言，到牧马童子论治理、各类人物囿于物，理解欲望、权力、言说与生命安顿之间的关系。","frontmatter":{"title":"庄子·徐无鬼","description":"从徐无鬼见魏武侯、相狗相马与真人之言，到牧马童子论治理、各类人物囿于物，理解欲望、权力、言说与生命安顿之间的关系。","category":"guide","aliases":["徐无鬼","庄子徐无鬼","zhuangzi chapter 24"],"source":["《庄子·杂篇·徐无鬼》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-24.md","filePath":"daoism/zhuang-zi/chapter-24.md","lastUpdated":1792641266000}'),O={name:"daoism/zhuang-zi/chapter-24.md"},X=K({...O,setup(U){const p=[{id:"xwg_audience_s1",label:"武侯慰劳：徐无鬼反问",sentences:[[{text:"徐无鬼",glossary:"xwg_audience_xuwugui"},"因",{text:"女商",glossary:"xwg_audience_nvshang"},"见魏武侯，武侯",{text:"劳",glossary:"xwg_audience_lao"},"之曰：「先生",{text:"病",glossary:"xwg_audience_bing"},"矣，苦于山林之劳，故乃肯见于寡人。」"],["徐无鬼曰：「我则劳于君，君有何劳于我！"],["君将",{text:"盈耆欲",glossary:"xwg_audience_yingqi"},"，长好恶，则性命之情病矣；君将",{text:"黜耆欲",glossary:"xwg_audience_chuqi"},"，牵好恶，则耳目病矣。"],["我将劳君，君有何劳于我！」武侯",{text:"超然不对",glossary:"xwg_audience_chaoran"},"。"]]},{id:"xwg_audience_s2",label:"相狗：下、中、上三种品质",sentences:[["少焉，徐无鬼曰：「尝语君吾",{text:"相狗",glossary:"xwg_audience_xianggou"},"也："],["下之质，",{text:"执饱而止",glossary:"xwg_audience_zhibao"},"，是狸德也；中之质，",{text:"若视日",glossary:"xwg_audience_shiri"},"；上之质，",{text:"若亡其一",glossary:"xwg_audience_wangyi"},"。"]]},{id:"xwg_audience_s3",label:"国马与天下马：标准与成材",sentences:[["吾相狗又不若吾",{text:"相马",glossary:"xwg_audience_xiangma"},"也。吾相马：直者",{text:"中绳",glossary:"xwg_audience_zhongsheng"},"，曲者",{text:"中钩",glossary:"xwg_audience_zhonggou"},"，方者",{text:"中矩",glossary:"xwg_audience_zhongju"},"，圆者",{text:"中规",glossary:"xwg_audience_zhonggui"},"。"],["是国马也，而未若天下马也。天下马有成材，",{text:"若卹若失，若丧其一",glossary:"xwg_audience_xu"},"。"],["若是者，超轶绝尘，不知其所。」武侯大悦而笑。"]]},{id:"xwg_audience_s4",label:"女商追问：何以说吾君",sentences:[["徐无鬼出，女商曰：「先生独何以",{text:"说",glossary:"xwg_audience_shuo"},"吾君乎？"],["吾所以说吾君者，横说之则以《诗》、《书》、《礼》、《乐》，",{text:"从说",glossary:"xwg_audience_congshuo"},"则以《",{text:"金板",glossary:"xwg_audience_jinban"},"》、《",{text:"六韬",glossary:"xwg_audience_liutao"},"》，"],["奉事而大有功者不可为数，而吾君未尝启齿。"],["今先生何以说吾君？使吾君说若此乎？」"],["徐无鬼曰：「吾直告之吾相狗马耳。」女商曰：「若是乎？」"]]},{id:"xwg_audience_s5",label:"越之流人：离人越久，思人越深",sentences:[["曰：「子不闻夫越之流人乎？去国数日，见其所知而喜；"],["去国旬月，见所尝见于国中者喜；及",{text:"期年",glossary:"xwg_audience_qinian"},"也，见似人者而喜矣。"],["不亦去人滋久，思人滋深乎？"]]},{id:"xwg_audience_s6",label:"荒处闻足音：真人之言久不在侧",sentences:[["夫逃虚空者，",{text:"藜藋",glossary:"xwg_audience_lidiao"},"柱乎",{text:"鼪鼬",glossary:"xwg_audience_shengyou"},"之径，良位其空，闻人足音",{text:"跫然",glossary:"xwg_audience_qiongran"},"而喜矣，"],["又况乎昆弟亲戚之",{text:"謦欬",glossary:"xwg_audience_qingkai"},"其侧者乎！"],["久矣夫，莫以真人之言謦欬吾君之侧乎！」"]]}],d=[{id:"xwg_audience_xuwugui",term:"徐无鬼",pinyin:"xú wú guǐ",meaning:"本段的来访者，因女商而见魏武侯。人物身份依篇中叙述理解，不预先断定其可考的历史身世或已完成某种境界。"},{id:"xwg_audience_nvshang",term:"女商",pinyin:"rǔ shāng",meaning:"本篇的引荐者，与徐无鬼同见魏武侯，并为徐无鬼能令武侯喜悦而惊讶。"},{id:"xwg_audience_lao",term:"劳",pinyin:"láo",meaning:"此处指慰劳。武侯「劳之」而被反问「我则劳于君，君有何劳于我」，慰劳的方向被反转。"},{id:"xwg_audience_bing",term:"病",pinyin:"bìng",meaning:"可指辛苦、困苦或受损。原文「先生病矣」「性命之情病矣」「耳目病矣」三处连读，不必每处都作现代医学疾病理解。"},{id:"xwg_audience_yingqi",term:"盈耆欲",pinyin:"yíng shì yù",meaning:"满足嗜欲。耆联系嗜理解，可读 shì，亦有其他注音。与黜耆欲相对，不等于任何满足都有害。"},{id:"xwg_audience_chuqi",term:"黜耆欲",pinyin:"chù shì yù",meaning:"强行压退嗜欲。与盈耆欲并列，两端皆病，说明问题不在欲望的数量本身。"},{id:"xwg_audience_chaoran",term:"超然不对",pinyin:"chāo rán bù duì",meaning:"惊动、怅然或有所触动而不答等，具体解释有差异。不能据此认定武侯已经领悟全部指引。"},{id:"xwg_audience_xianggou",term:"相狗",pinyin:"xiàng gǒu",meaning:"观察、鉴别狗。是寓言中的品评，不直接作为现代动物行为学或选育标准。"},{id:"xwg_audience_xiangma",term:"相马",pinyin:"xiàng mǎ",meaning:"观察、鉴别马。与相狗并举，说明品评自有层次，并引出「国马」与「天下马」之分。"},{id:"xwg_audience_zhibao",term:"执饱而止",pinyin:"zhí bǎo ér zhǐ",meaning:"狗的「下之质」，吃饱便止。具体神态与性情解释有空间。"},{id:"xwg_audience_shiri",term:"若视日",pinyin:"ruò shì rì",meaning:"狗的「中之质」，目光如视日。不能直接定为有志向。"},{id:"xwg_audience_wangyi",term:"若亡其一",pinyin:"ruò wáng qí yī",meaning:"狗的「上之质」，仿佛忘失自身。不能直接定为放下全部目标。"},{id:"xwg_audience_zhongsheng",term:"中绳",pinyin:"zhòng shéng",meaning:"符合墨绳。中读 zhòng，意为符合。原文承认此类国马之优，不是一概否定标准。"},{id:"xwg_audience_zhonggou",term:"中钩",pinyin:"zhòng gōu",meaning:"符合钩尺。与中绳、中矩、中规并举，写「国马」之优。"},{id:"xwg_audience_zhongju",term:"中矩",pinyin:"zhòng jǔ",meaning:"符合矩尺。四者合看，可见标准之内仍有「天下马」更高的层次。"},{id:"xwg_audience_zhonggui",term:"中规",pinyin:"zhòng guī",meaning:"符合圆规。四者并举，原文并不否定尺度，只限制其为充分条件。"},{id:"xwg_audience_xu",term:"若卹若失，若丧其一",pinyin:"ruò xù ruò shī, ruò sàng qí yī",meaning:"像有所忧、若有所失的神态。卹亦有异体写法；不能由此直接推出马已经超越形体或获得无目标的自由。"},{id:"xwg_audience_shuo",term:"说",pinyin:"shuì／yuè",meaning:"在劝说义读 shuì，在使喜悦、喜悦义可读 yuè。女商所问「何以说吾君」兼具劝进与取悦两面。"},{id:"xwg_audience_congshuo",term:"从说",pinyin:"zòng shuì",meaning:"与「横说之」相对，指另一种说进方式。不能强定为横向角度与纵向历史。"},{id:"xwg_audience_jinban",term:"金板",pinyin:"jīn bǎn",meaning:"古代典籍之名。所指与相关文本的关系宜依注本处理，不直接等同今天通行的某一完整书本。"},{id:"xwg_audience_liutao",term:"六韬",pinyin:"liù tāo",meaning:"兵政谋略之书。与金板并列，说明女商进说所用皆为当时公认的典籍。"},{id:"xwg_audience_qinian",term:"期年",pinyin:"jī nián",meaning:"满一年，期在此读 jī。见似人者可联系像故国之人者理解，不必译成任何外形像人的东西。"},{id:"xwg_audience_lidiao",term:"藜藋",pinyin:"lí diào",meaning:"荒草。与鼪鼬之径连读，写荒僻无人之境。"},{id:"xwg_audience_shengyou",term:"鼪鼬",pinyin:"shēng yòu",meaning:"鼪、鼬等兽类。柱、良位的字形训释有差异，不强定为野草堵住单一物种的小径。"},{id:"xwg_audience_qiongran",term:"跫然",pinyin:"qióng rán",meaning:"足音。以听到人的脚步写久处荒野后重获相接。"},{id:"xwg_audience_qingkai",term:"謦欬",pinyin:"qǐng kài",meaning:"咳嗽之声。与跫然并举，不意味着真实言说必须音量轻、字数少。"}],u=[{id:"xwg_governance_s1",label:"山林饮食与来意：不是求酒肉",sentences:[["徐无鬼见武侯，武侯曰：「先生居山林，",{text:"食芧栗，厌葱韭",glossary:"xwg_governance_xuli"},"，以宾寡人，久矣夫！"],["今老邪？其欲",{text:"干酒肉之味",glossary:"xwg_governance_gan"},"邪？其寡人亦有社稷之福邪？」"],["徐无鬼曰：「无鬼生于贫贱，未尝敢饮食君之酒肉，将来劳君也。」"]]},{id:"xwg_governance_s2",label:"劳神与形：天地之养也一",sentences:[["君曰：「何哉！奚劳寡人？」曰：「劳君之神与形。」"],["武侯曰：「何谓邪？」徐无鬼曰：「",{text:"天地之养也一",glossary:"xwg_governance_yang"},"，登高不可以为长，居下不可以为短。"],["君独为万乘之主，以苦一国之民，以养耳目鼻口，夫神者",{text:"不自许",glossary:"xwg_governance_buzixu"},"也。"],["夫神者，",{text:"好和而恶奸",glossary:"xwg_governance_haohe"},"。夫奸，病也，故劳之。唯君所病之何也？」"]]},{id:"xwg_governance_s3",label:"爱民为义偃兵：徐无鬼提出反诘",sentences:[["武侯曰：「欲见先生久矣！吾欲爱民而",{text:"为义偃兵",glossary:"xwg_governance_yanbing"},"，其可乎？」"],["徐无鬼曰：「不可。爱民，害民之始也；为义偃兵，造兵之本也。"],["君自此为之，则殆不成。",{text:"凡成美，恶器也",glossary:"xwg_governance_chengmei"},"。君虽为仁义，几且伪哉！"],[{text:"形固造形，成固有伐，变固外战",glossary:"xwg_governance_xing"},"。"]]},{id:"xwg_governance_s4",label:"六个无：不以巧、谋、战胜人",sentences:[["君亦必无盛",{text:"鹤列",glossary:"xwg_governance_helie"},"于",{text:"丽谯",glossary:"xwg_governance_liqiao"},"之间，无",{text:"徒骥",glossary:"xwg_governance_tuji"},"于",{text:"锱坛",glossary:"xwg_governance_zitan"},"之宫，无藏逆于得，"],["无以巧胜人，无以谋胜人，无以战胜人。"]]},{id:"xwg_governance_s5",label:"兼地杀民，何善何胜",sentences:[["夫杀人之士民，兼人之土地，以养吾私与吾神者，其战不知孰善？胜之恶乎在？"]]},{id:"xwg_governance_s6",label:"修胸中之诚：应天地而勿撄",sentences:[[{text:"君若勿已矣",glossary:"xwg_governance_wuyi"},"！",{text:"修胸中之诚以应天地之情而勿撄",glossary:"xwg_governance_cheng"},"。"],[{text:"夫民死已脱矣",glossary:"xwg_governance_minsi"},"，君将恶乎用夫偃兵哉！」"]]}],x=[{id:"xwg_governance_xuli",term:"食芧栗，厌葱韭",pinyin:"shí xù lì, yàn cōng jiǔ",meaning:"以橡实、栗与葱韭等山林食物为食。厌有饱足等解释，不必定为吃腻。"},{id:"xwg_governance_gan",term:"干酒肉之味",pinyin:"gān jiǔ ròu zhī wèi",meaning:"求取酒肉之味，干有求取义。不必只解释成尝一口酒肉。"},{id:"xwg_governance_yang",term:"天地之养也一",pinyin:"tiān dì zhī yǎng yě yī",meaning:"以天地之养松开贵贱高下的绝对区分。不等于现实资源分配已经平等，也不否认政治地位带来的实际差异。"},{id:"xwg_governance_buzixu",term:"不自许",pinyin:"bù zì xǔ",meaning:"神不认可、不安于这种处身方式。原文「夫神者不自许也」承「以苦一国之民，以养耳目鼻口」而言。"},{id:"xwg_governance_haohe",term:"好和而恶奸",pinyin:"hào hé ér wù jiān",meaning:"神好和而恶奸。奸可联系侵害、扰乱与不和理解，不只指现代道德意义上的奸诈。"},{id:"xwg_governance_yanbing",term:"为义偃兵",pinyin:"wéi yì yǎn bīng",meaning:"以义的名义止兵、息兵，具体政治含义需连同后文胜人、杀民兼地理解，不必等同取消军队或全部防卫。"},{id:"xwg_governance_chengmei",term:"凡成美，恶器也",pinyin:"fán chéng měi, è qì yě",meaning:"将成就美名、美事与可能造成恶的器具相接，语义有解释空间。不能直接推出凡有善意、目的或成果都会造成更大恶。"},{id:"xwg_governance_xing",term:"形固造形，成固有伐，变固外战",pinyin:"xíng gù zào xíng, chéng gù yǒu fá, biàn gù wài zhàn",meaning:"形、成、变与相应后果相接，是疑难语群。伐有自伐、夸功及攻伐等解释，不直接译成所有成就必然征伐、所有变革必然扩张。"},{id:"xwg_governance_helie",term:"鹤列",pinyin:"hè liè",meaning:"涉及陈列、军列等，字形与具体名物有不同解释。不未经校定便作军阵解。"},{id:"xwg_governance_liqiao",term:"丽谯",pinyin:"lì qiáo",meaning:"楼观之名。与鹤列连读，写盛大的陈列与建筑。"},{id:"xwg_governance_tuji",term:"徒骥",pinyin:"tú jì",meaning:"涉及步卒与马匹等，解释有差异。与锱坛之宫连读，写宫室中的陈设。"},{id:"xwg_governance_zitan",term:"锱坛",pinyin:"zī tán",meaning:"宫室之名，具体所指有不同解释。不未经校定便作祭坛解。"},{id:"xwg_governance_wuyi",term:"君若勿已矣",pinyin:"jūn ruò wù yǐ yǐ",meaning:"若你仍不肯停止、若必须继续有所为等，有不同解释。不能按字面反译成你不如停下来。"},{id:"xwg_governance_cheng",term:"修胸中之诚以应天地之情而勿撄",pinyin:"xiū xiōng zhōng zhī chéng yǐ yìng tiān dì zhī qíng ér wù yīng",meaning:"修整内在真实，以应接天地情状而不侵扰。诚不只是自我感觉真诚，仍需与是否苦民、侵害连读。"},{id:"xwg_governance_minsi",term:"夫民死已脱矣",pinyin:"fū mín sǐ yǐ tuō yǐ",meaning:"疑难句，涉及民之死、脱离或免于死患等解释。最终依底本校定，不将死亡直接赞为百姓应追求的解脱。"}],_=[{id:"xwg_herding_s1",label:"黄帝寻大隗：七圣皆迷",sentences:[["黄帝将见",{text:"大隗",glossary:"xwg_herding_dawei"},"乎",{text:"具茨",glossary:"xwg_herding_juci"},"之山，方明为御，昌寓",{text:"骖乘",glossary:"xwg_herding_cansheng"},"，张若、谐朋前马，昆阍、滑稽后车。"],["至于襄城之野，",{text:"七圣皆迷",glossary:"xwg_herding_qisheng"},"，无所问涂。"]]},{id:"xwg_herding_s2",label:"童子知路：由问涂转问天下",sentences:[["适遇牧马童子，问涂焉，曰：「若知具茨之山乎？」曰：「然。」"],["「若知大隗之所存乎？」曰：「然。」"],["黄帝曰：「异哉小童！非徒知具茨之山，又知大隗之所存。请问为天下。」"]]},{id:"xwg_herding_s3",label:"瞀病与游：亦若此而已",sentences:[["小童曰：「夫为天下者，亦若此而已矣，又奚事焉！"],["予少而自游于",{text:"六合之内",glossary:"xwg_herding_liuhe"},"，予适有",{text:"瞀病",glossary:"xwg_herding_mao"},"，有长者教予曰："],["『若",{text:"乘日之车",glossary:"xwg_herding_riche"},"而游于襄城之野。』"],["今予病少痊，予又且复游于",{text:"六合之外",glossary:"xwg_herding_liuhewai"},"。"],["夫为天下亦若此而已。予又奚事焉！」"]]},{id:"xwg_herding_s4",label:"黄帝再问：童子先辞",sentences:[["黄帝曰：「夫为天下者，则诚非吾子之事，虽然，请问为天下。」"],["小童辞。黄帝又问。"]]},{id:"xwg_herding_s5",label:"牧马之喻：去害而不多事",sentences:[["小童曰：「夫为天下者，亦奚以异乎牧马者哉！亦",{text:"去其害马者",glossary:"xwg_herding_hai"},"而已矣！」"],["黄帝",{text:"再拜稽首",glossary:"xwg_herding_qishou"},"，称天师而退。"]]}],m=[{id:"xwg_herding_dawei",term:"大隗",pinyin:"dà wěi",meaning:"篇中所寻人物。人物与山名的关系依寓言阅读，不据此考订史实。"},{id:"xwg_herding_juci",term:"具茨",pinyin:"jù cí",meaning:"山名。地理对应可另考，不以现代地点定位取代寓言阅读。"},{id:"xwg_herding_cansheng",term:"骖乘",pinyin:"cān shèng",meaning:"陪乘、车右等，乘在此常读 shèng。御指驾车，前马与后车写行列中的前导和后随。"},{id:"xwg_herding_qisheng",term:"七圣皆迷",pinyin:"qī shèng jiē mí",meaning:"黄帝加六位同行者，共七人，不是黄帝另带七位圣人。涂联系途、道路理解。"},{id:"xwg_herding_mao",term:"瞀病",pinyin:"mào bìng",meaning:"昏眩、昏乱之病等，寓意有解释空间。不能确定病因是外物使其失去中心，也不是现代诊断。"},{id:"xwg_herding_riche",term:"乘日之车",pinyin:"chéng rì zhī chē",meaning:"寓言中的游行表达，可联系顺日、自然运行理解，也有其他解释。不作治疗眩晕的现实方法。"},{id:"xwg_herding_liuhe",term:"六合之内",pinyin:"liù hé zhī nèi",meaning:"六合指天地四方，之内涉及游的范围。不必定为一级境界。"},{id:"xwg_herding_liuhewai",term:"六合之外",pinyin:"liù hé zhī wài",meaning:"与六合之内相对，属寓言想象的游行范围。不作实际离开宇宙的主张。"},{id:"xwg_herding_hai",term:"去其害马者",pinyin:"qù qí hài mǎ zhě",meaning:"去除妨害马的因素。害马者具体所指未列明，不能只定为训练、管制或使用，也不能扩大为对所谓有害者的惩杀原则。"},{id:"xwg_herding_qishou",term:"再拜稽首",pinyin:"zài bài qǐ shǒu",meaning:"拜而叩首的尊敬礼节。称天师是本段称谓，不直接等同后世道教职衔。"}],h=[{id:"xwg_bound_s1",label:"知、辩、察：无其事则不乐",sentences:[["知士无思虑之变则不乐；辩士无谈说之序则不乐；察士无",{text:"凌谇",glossary:"xwg_bound_lingsui"},"之事则不乐："],["皆",{text:"囿于物",glossary:"xwg_bound_you"},"者也。"]]},{id:"xwg_bound_s2",label:"九类士人：各有所重",sentences:[[{text:"招世",glossary:"xwg_bound_zhaoshi"},"之士兴朝；",{text:"中民",glossary:"xwg_bound_zhongmin"},"之士荣官；",{text:"筋国",glossary:"xwg_bound_jinguo"},"之士",{text:"矜雅",glossary:"xwg_bound_jinya"},"；"],["勇敢之士奋患；兵革之士乐战；",{text:"枯槁之士宿名",glossary:"xwg_bound_suming"},"；"],["法律之士广治；礼乐之士敬容；",{text:"仁义之士贵际",glossary:"xwg_bound_guiji"},"。"]]},{id:"xwg_bound_s3",label:"农工商与庶人：事务、勤勉和技巧",sentences:[["农夫无草莱之事则",{text:"不比",glossary:"xwg_bound_bubi"},"；商贾无市井之事则不比；"],["庶人有旦暮之业则",{text:"劝",glossary:"xwg_bound_quan"},"；百工有器械之巧则",{text:"壮",glossary:"xwg_bound_zhuang"},"。"]]},{id:"xwg_bound_s4",label:"贪、夸与势物：忧悲和时机",sentences:[["钱财不积则贪者忧，权势不尤则夸者悲，势物之徒乐变。"],["遭时有所用，不能无为也，此皆",{text:"顺比于岁，不物于易",glossary:"xwg_bound_suiyi"},"者也。"]]},{id:"xwg_bound_s5",label:"驰形性，潜万物：终身不反",sentences:[[{text:"驰其形性，潜之万物",glossary:"xwg_bound_chi"},"，终身不反，悲夫！"]]}],y=[{id:"xwg_bound_you",term:"囿于物",pinyin:"yòu yú wù",meaning:"被事物、所业、所重的对象圈住。物不只指物质财物，也可涉及议论、名誉和身份活动。"},{id:"xwg_bound_lingsui",term:"凌谇",pinyin:"líng suì",meaning:"凌厉责问、诘责等，不只指普通批评。谈说之序的序涉及次序、条理或场合等，有不同解释。"},{id:"xwg_bound_zhaoshi",term:"招世",pinyin:"zhāo shì",meaning:"招引世人。与中民、筋国、矜雅并列，具体解释有不同说法。"},{id:"xwg_bound_zhongmin",term:"中民",pinyin:"zhòng mín",meaning:"不宜直接定为中等民众，音义依注本统一。"},{id:"xwg_bound_jinguo",term:"筋国",pinyin:"jīn guó",meaning:"与强国、劳形于国等解释相关。"},{id:"xwg_bound_jinya",term:"矜雅",pinyin:"jīn yǎ",meaning:"自矜其所长；雅也不只作礼仪雅正。"},{id:"xwg_bound_suming",term:"枯槁之士宿名",pinyin:"kū gǎo zhī shì sù míng",meaning:"朴苦、隐处之士仍寄托于名声等。宿可联系所止、所寄理解，不据此断言所有隐者都蓄意借隐居求名。"},{id:"xwg_bound_guiji",term:"仁义之士贵际",pinyin:"rén yì zhī shì guì jì",meaning:"重视交接、关系中的仁义等，有不同解释。际不必作抓住仁义时机，也不能据此取消关怀他人的价值。"},{id:"xwg_bound_bubi",term:"不比",pinyin:"bù bǐ",meaning:"比涉及亲附、安于所业等解释。不能将全部词统一译成没工作就焦虑。"},{id:"xwg_bound_quan",term:"劝",pinyin:"quàn",meaning:"指勤勉、受到激励。"},{id:"xwg_bound_zhuang",term:"壮",pinyin:"zhuàng",meaning:"指振奋、意气盛。"},{id:"xwg_bound_suiyi",term:"顺比于岁，不物于易",pinyin:"shùn bǐ yú suì, bù wù yú yì",meaning:"疑难句，涉及依随时势与不能妥善处变化等。物、易的句法有讨论空间，不强定为无法超越宇宙变化。"},{id:"xwg_bound_chi",term:"驰其形性，潜之万物",pinyin:"chí qí xíng xìng, qián zhī wàn wù",meaning:"使形性奔逐，沉入万物与所事之中。反联系返、返回理解，未必要求物理上退出社会或停止劳动。"}],c=p.map(l=>({...l,sentences:l.sentences})),w=[{id:"xwg_resonance_s1",label:"善射之问：是否先定目标",sentences:[["庄子曰：「射者",{text:"非前期而中",glossary:"xwg_resonance_qianqi"},"谓之善射，天下皆羿也，可乎？」"],["惠子曰：「可。」"]]},{id:"xwg_resonance_s2",label:"各是其所是：天下皆尧",sentences:[["庄子曰：「天下非有",{text:"公是",glossary:"xwg_resonance_gongshi"},"也，而",{text:"各是其所是",glossary:"xwg_resonance_geshi"},"，天下皆尧也，可乎？」"],["惠子曰：「可。」"]]},{id:"xwg_resonance_s3",label:"五家争是：鲁遽弟子自称得道",sentences:[["庄子曰：「然则",{text:"儒墨杨秉",glossary:"xwg_resonance_yangbing"},"四，与夫子为五，果孰是邪？或者若",{text:"鲁遽",glossary:"xwg_resonance_luju"},"者邪？"],["其弟子曰：『我得夫子之道矣！吾能",{text:"冬爨鼎而夏造冰",glossary:"xwg_resonance_cuan"},"矣！』"]]},{id:"xwg_resonance_s4",label:"同类相召：未必穷尽所说道",sentences:[["鲁遽曰：『是直以阳召阳，以阴召阴，非吾所谓道也。吾示子乎吾道。』"]]},{id:"xwg_resonance_s5",label:"两瑟相应：宫动与角动",sentences:[["于是乎为之调瑟，",{text:"废一于堂，废一于室",glossary:"xwg_resonance_fei"},"，",{text:"鼓宫宫动，鼓角角动",glossary:"xwg_resonance_gongjiao"},"，音律同矣！"]]},{id:"xwg_resonance_s6",label:"改调一弦：五音无当而众弦皆动",sentences:[["夫或改调一弦，于",{text:"五音无当",glossary:"xwg_resonance_wuyin"},"也，鼓之，二十五弦皆动，"],[{text:"未始异于声而音之君已",glossary:"xwg_resonance_yinzhijun"},"！且若是者邪！」"]]}],b=[{id:"xwg_resonance_qianqi",term:"非前期而中",pinyin:"fēi qián qī ér zhòng",meaning:"未事先约定、确定所射目标，却称为射中。语气与论证方式有解释空间；可先注意未定目标时，射中这一评价如何成立。中读 zhòng。"},{id:"xwg_resonance_gongshi",term:"公是",pinyin:"gōng shì",meaning:"共同认可或可共同据以判断的是。与各是其所是相对，不直接等同已经证明任何公共判断都不可能。"},{id:"xwg_resonance_geshi",term:"各是其所是",pinyin:"gè shì qí suǒ shì",meaning:"各自认定自己所是。与公是相对，说明并无现成、可直接占有的公共真理。"},{id:"xwg_resonance_yangbing",term:"儒墨杨秉",pinyin:"rú mò yáng bǐng",meaning:"儒、墨、杨及秉等论说立场。杨通常联系杨朱，秉有联系公孙龙字子秉等解释；具体所指依注本处理，不另造一个身份确定的秉学派。"},{id:"xwg_resonance_luju",term:"鲁遽",pinyin:"lǔ jù",meaning:"寓言中的老师，具体身世不详。不必先定为已经完成某级境界的历史人物。"},{id:"xwg_resonance_cuan",term:"冬爨鼎而夏造冰",pinyin:"dōng cuàn dǐng ér xià zào bīng",meaning:"冬日烧鼎、夏日造冰，后文以阴阳同类相召解释。爨：烧火炊煮。造冰具体方式未交代，不能补成用现成冰制造冷。"},{id:"xwg_resonance_fei",term:"废一于堂，废一于室",pinyin:"fèi yī yú táng, fèi yī yú shì",meaning:"各放置一张瑟于堂、室，废在此联系置、放置理解，不作废弃乐器解。"},{id:"xwg_resonance_gongjiao",term:"鼓宫宫动，鼓角角动",pinyin:"gǔ gōng gōng dòng, gǔ jué jué dòng",meaning:"弹奏宫、角，相应音弦随之振动。角作为五音之一读 jué，不读 jiǎo。可与共鸣对读，不将全部寓言细节当作现代声学实验。"},{id:"xwg_resonance_wuyin",term:"五音无当",pinyin:"wǔ yīn wú dàng",meaning:"与宫、商、角、徵、羽的既定音位不相当。五音读 gōng、shāng、jué、zhǐ、yǔ。不能直接推出该弦不是声音，或任何不合标准之物都能贯通全部。"},{id:"xwg_resonance_yinzhijun",term:"未始异于声而音之君已",pinyin:"wèi shǐ yì yú shēng ér yīn zhī jūn yǐ",meaning:"仍未离开声，却被称为音之君等，具体句法有讨论空间。不能把未始异于声反译为从不属于声音，也不直接等同唯一的公共真理。"}],q=[{id:"xwg_dispute_s1",label:"惠子续问：言辞与声势的相争",sentences:[["惠子曰：「今乎儒墨杨秉，且方与我以辩，",{text:"相拂以辞，相镇以声",glossary:"xwg_dispute_fuzhen"},"，"],["而",{text:"未始吾非也",glossary:"xwg_dispute_wufei"},"，则奚若矣？」"]]},{id:"xwg_dispute_s2",label:"齐人之喻：蹢子、阍与完",sentences:[["庄子曰：「",{text:"齐人蹢子于宋",glossary:"xwg_dispute_dizi"},"者，其",{text:"命阍也不以完",glossary:"xwg_dispute_hun"},"；"]]},{id:"xwg_dispute_s3",label:"求取的疑难语群：钘钟与唐子",sentences:[["其求",{text:"钘钟",glossary:"xwg_dispute_xingzhong"},"也以束缚；其求",{text:"唐子",glossary:"xwg_dispute_tangzi"},"也而未始出域：",{text:"有遗类",glossary:"xwg_dispute_yilei"},"矣！"]]},{id:"xwg_dispute_s4",label:"楚人之喻：斗而造怨",sentences:[["夫",{text:"楚人寄而蹢阍",glossary:"xwg_dispute_jidi"},"者；夜半于无人之时而与舟人斗，"],[{text:"未始离于岑",glossary:"xwg_dispute_cen"},"而足以造于怨也。」"]]}],f=[{id:"xwg_dispute_fuzhen",term:"相拂以辞，相镇以声",pinyin:"xiāng fú yǐ cí, xiāng zhèn yǐ shēng",meaning:"以言辞相互拂逆，以声音、声势相互压制。描述争辩方式，不等于一切论证和讨论都如此。"},{id:"xwg_dispute_wufei",term:"未始吾非也",pinyin:"wèi shǐ wú fēi yě",meaning:"有我未曾自以为非、未被判非等不同理解。不能只据此认定对手从未反驳、惠子已经客观赢得所有辩论。"},{id:"xwg_dispute_dizi",term:"齐人蹢子于宋",pinyin:"qí rén zhí zǐ yú sòng",meaning:"蹢有弃置等解释，整句及后续关联存在训释问题。暂按来稿保留，不自行补写此人随后决定寻找孩子的完整经过。"},{id:"xwg_dispute_hun",term:"命阍也不以完",pinyin:"mìng hūn yě bù yǐ wán",meaning:"阍涉及守门者，完有完整、身体完整等解释。不能仅定为任命或命令守门人时不使用完整礼节。"},{id:"xwg_dispute_xingzhong",term:"钘钟",pinyin:"xíng zhōng",meaning:"字形、所指与求字意义有争议。钘有器物相关古义，但不能仅凭钟字定为乐器，更不能据束缚补成用绳子寻找乐器。"},{id:"xwg_dispute_tangzi",term:"唐子",pinyin:"táng zǐ",meaning:"疑难用语，所指与异文需依底本校定。不在此立为身份确定的虚构人物。"},{id:"xwg_dispute_yilei",term:"有遗类",pinyin:"yǒu yí lèi",meaning:"涉及遗漏、类别不相合或所求与所行失配等解释。可作为辨析求取方式的线索，不以一个现代译法穷尽全句。"},{id:"xwg_dispute_jidi",term:"楚人寄而蹢阍",pinyin:"chǔ rén jì ér zhí hūn",meaning:"寄、蹢、阍的组合及字形有讨论空间。保留疑难，不补成一个确定的寄居者抛弃守门人的故事。"},{id:"xwg_dispute_cen",term:"未始离于岑",pinyin:"wèi shǐ lí yú cén",meaning:"岑有高处、岸处等联系，也涉及不同校释。不能仅按小土堆建立格局狭小的唯一寓意。末句造怨较明确，指产生怨恨。"}],k=[{id:"xwg_partner_s1",label:"过惠子墓：向从者述往事",sentences:[[{text:"庄子送葬，过惠子之墓",glossary:"xwg_partner_songzang"},"，顾谓从者曰："]]},{id:"xwg_partner_s2",label:"鼻端薄垩：匠石运斤",sentences:[["「郢人",{text:"垩慢其鼻端若蝇翼",glossary:"xwg_partner_eman"},"，使匠人斫之。"],["匠石",{text:"运斤成风",glossary:"xwg_partner_jin"},"，",{text:"听而斫之",glossary:"xwg_partner_ting"},"，尽垩而鼻不伤，郢人立不失容。"]]},{id:"xwg_partner_s3",label:"宋元君求再作：质已死久",sentences:[["宋元君闻之，召匠石曰：『尝试为寡人为之。』"],["匠石曰：『臣则尝能斫之。虽然，",{text:"臣之质死久矣",glossary:"xwg_partner_shizhi"},"！』"]]},{id:"xwg_partner_s4",label:"由匠石及自身：无与言者",sentences:[["自夫子之死也，吾无以为质矣，",{text:"吾无与言之",glossary:"xwg_partner_yuyan"},"矣！」"]]}],z=[{id:"xwg_partner_songzang",term:"庄子送葬，过惠子之墓",pinyin:"zhuāng zǐ sòng zàng, guò huì zǐ zhī mù",meaning:"在送葬途中经过惠子墓。不是本句明确说庄子正在为惠子送葬。"},{id:"xwg_partner_eman",term:"垩慢其鼻端若蝇翼",pinyin:"è màn qí bí duān ruò yíng yì",meaning:"在鼻端涂白垩，薄如蝇翼。慢有涂污等解释，亦有字形处理差异，不作怠慢解。"},{id:"xwg_partner_jin",term:"运斤成风",pinyin:"yùn jīn chéng fēng",meaning:"挥运斧斤而生风，形容操作迅疾。斤：斧。是高度理想化的技艺故事，不作现实表演指导。"},{id:"xwg_partner_ting",term:"听而斫之",pinyin:"tīng ér zhuó zhī",meaning:"听有任、任运等解释，可联系从容挥斫。不只指靠听觉或凭未经训练的感觉操作。"},{id:"xwg_partner_shizhi",term:"臣之质死久矣",pinyin:"chén zhī zhì sǐ jiǔ yǐ",meaning:"那位能与之配合的对象已经死去。质：承受、配合其技艺或言说的对象、对手，可引申为相知的交谈者，但不是质字在所有语境中都等于知己。说明关系与条件不可替代，不必补成匠石当前全部技艺仍毫无变化。"},{id:"xwg_partner_yuyan",term:"吾无与言之",pinyin:"wú wú yǔ yán zhī",meaning:"失去能与之作这种交谈的人。是强烈哀悼，不必按字面认定庄子此后再未与任何人说话。"}],P=[{id:"xwg_appointment_s1",label:"管仲病重：桓公问托国",sentences:[["管仲有病，桓公问之曰：「",{text:"仲父",glossary:"xwg_appointment_zhongfu"},"之病病矣，可不讳云，"],["至于大病，则寡人",{text:"恶乎属国",glossary:"xwg_appointment_shuguo"},"而可？」"],["管仲曰：「公谁欲与？」公曰：「鲍叔牙。」"]]},{id:"xwg_appointment_s2",label:"善士未必相宜：不比、不忘人过",sentences:[["曰：「不可。其为人洁廉，善士也；其",{text:"于不己若者不比之",glossary:"xwg_appointment_bi"},"；"],["又",{text:"一闻人之过，终身不忘",glossary:"xwg_appointment_guo"},"。"],["使之治国，",{text:"上且钩乎君，下且逆乎民",glossary:"xwg_appointment_gou"},"。其得罪于君也将弗久矣！」"]]},{id:"xwg_appointment_s3",label:"隰朋可：愧己不及，哀人不及",sentences:[["公曰：「然则孰可？」对曰：「",{text:"勿已则隰朋可",glossary:"xwg_appointment_wuyi"},"。"],["其为人也，",{text:"上忘而下畔",glossary:"xwg_appointment_shangxia"},"，愧不若黄帝，而哀不己若者。"]]},{id:"xwg_appointment_s4",label:"分德分财：临人与下人",sentences:[[{text:"以德分人",glossary:"xwg_appointment_fen"},"谓之圣；",{text:"以财分人",glossary:"xwg_appointment_cai"},"谓之贤。"],[{text:"以贤临人",glossary:"xwg_appointment_linxia"},"，未有得人者也；",{text:"以贤下人",glossary:"xwg_appointment_xiaren"},"，未有不得人者也。"]]},{id:"xwg_appointment_s5",label:"有所不闻不见：再次荐隰朋",sentences:[["其",{text:"于国有不闻",glossary:"xwg_appointment_buwen"},"也，其",{text:"于家有不见",glossary:"xwg_appointment_bujian"},"也。勿已则",{text:"隰朋",glossary:"xwg_appointment_xipeng"},"可。」"]]}],j=[{id:"xwg_appointment_zhongfu",term:"仲父",pinyin:"zhòng fǔ",meaning:"桓公对管仲的尊称。病病写病重，大病涉及病势加重及身后托付，不是现代诊断名称。"},{id:"xwg_appointment_shuguo",term:"恶乎属国",pinyin:"wū hū zhǔ guó",meaning:"把国事托付给谁、何人相宜。属读 zhǔ，意为托付；不是属国这一现代常用名词。"},{id:"xwg_appointment_bi",term:"于不己若者不比之",pinyin:"yú bù jǐ ruò zhě bù bǐ zhī",meaning:"不亲近、不相与不如自己的人。比涉及亲附、相与，不只指比较能力高低。"},{id:"xwg_appointment_guo",term:"一闻人之过，终身不忘",pinyin:"yī wén rén zhī guò, zhōng shēn bù wàng",meaning:"将他人的过失长期固定地记住。不能径直补成他人曾伤害自己、因此记仇；重点在如何对待别人的过失。"},{id:"xwg_appointment_gou",term:"上且钩乎君，下且逆乎民",pinyin:"shàng qiě gōu hū jūn, xià qiě nì hū mín",meaning:"对君形成牵制、拘束，对民造成抵牾等。钩、逆的具体义项有差异，不应由此说劝谏君主本身错误。"},{id:"xwg_appointment_xipeng",term:"隰朋",pinyin:"xí péng",meaning:"齐国人物。本段为托国问答中的推荐者，阅读时仍须区分寓言叙述与严格历史记录。"},{id:"xwg_appointment_shangxia",term:"上忘而下畔",pinyin:"shàng wàng ér xià pàn",meaning:"上、下、忘、畔的关系有不同解释，亦有联系忘权位、亲附于下者。不能只按畔的叛逆义，或只定为不管束百姓。"},{id:"xwg_appointment_fen",term:"以德分人",pinyin:"yǐ dé fēn rén",meaning:"与人分享德的惠益。原文谓之为圣，肯定分享而非否定德。"},{id:"xwg_appointment_cai",term:"以财分人",pinyin:"yǐ cái fēn rén",meaning:"与人分享财物。原文谓之为贤，不是一概否定财与贤。"},{id:"xwg_appointment_linxia",term:"以贤临人",pinyin:"yǐ xián lín rén",meaning:"以贤能居高临人。原文谓「未有得人者也」，与以贤下人相对。"},{id:"xwg_appointment_xiaren",term:"以贤下人",pinyin:"yǐ xián xià rén",meaning:"有贤能而能谦下。理想化表达，不作谦下必然获所有人认可的保证。"},{id:"xwg_appointment_buwen",term:"于国有不闻",pinyin:"yú guó yǒu bù wén",meaning:"有些事不必尽闻尽见，可联系不苛察、保留余地理解。不是允许隐瞒侵害或放弃监督。"},{id:"xwg_appointment_bujian",term:"于家有不见",pinyin:"yú jiā yǒu bù jiàn",meaning:"与于国有不闻并列，写容人所需要的余地，不是纵容违法。"},{id:"xwg_appointment_wuyi",term:"勿已则隰朋可",pinyin:"wù yǐ zé xí péng kě",meaning:"若必须有所托付、不能止于此，则隰朋可等。与其他篇目的不得已可对读，但不证明管仲没有经过考量、只是本能推荐。"}],T=[{id:"xwg_monkey_s1",label:"吴王登山：众狙避走",sentences:[["吴王浮于江，登乎狙之山，众",{text:"狙",glossary:"xwg_monkey_ju"},"见之，",{text:"恂然",glossary:"xwg_monkey_xunran"},"弃而走，逃于",{text:"深蓁",glossary:"xwg_monkey_shenzhen"},"。"]]},{id:"xwg_monkey_s2",label:"一狙见巧：敏捷仍不能免于齐射",sentences:[["有一狙焉，委蛇",{text:"攫𢮞",glossary:"xwg_monkey_juesou"},"，",{text:"见巧乎王",glossary:"xwg_monkey_xianqiao"},"。"],["王射之，",{text:"敏给搏捷矢",glossary:"xwg_monkey_minji"},"。王命",{text:"相者趋射之",glossary:"xwg_monkey_xiangzhe"},"，狙执死。"]]},{id:"xwg_monkey_s3",label:"吴王解释：以此戒颜不疑",sentences:[["王顾谓其友",{text:"颜不疑",glossary:"xwg_monkey_yanbuyi"},"曰：「之狙也，",{text:"伐其巧",glossary:"xwg_monkey_faqiao"},"、恃其便以敖予，以至此",{text:"殛",glossary:"xwg_monkey_ji2"},"也。"],["戒之哉！嗟乎！无以汝色骄人哉？」"]]},{id:"xwg_monkey_s4",label:"颜不疑求师：锄其色、辞显",sentences:[["颜不疑归而师",{text:"董梧",glossary:"xwg_monkey_dongwu"},"，以",{text:"锄其色",glossary:"xwg_monkey_chuse"},"，",{text:"去乐辞显",glossary:"xwg_monkey_quleshixian"},"，三年而国人称之。"]]}],v=[{id:"xwg_monkey_ju",term:"狙",pinyin:"jū",meaning:"猴类。众狙见吴王而弃走，不由其逃走便断言具有完整的危险判断。"},{id:"xwg_monkey_xunran",term:"恂然",pinyin:"xún rán",meaning:"惊惧之状。"},{id:"xwg_monkey_shenzhen",term:"深蓁",pinyin:"shēn zhēn",meaning:"蓁联系草木丛生之处理解，众狙逃于其中。"},{id:"xwg_monkey_juesou",term:"委蛇攫𢮞",pinyin:"wēi yí jué sǒu",meaning:"写猴的活动、抓取跳跃等。𢮞的字形、音义须依注本校定；委蛇不自动证明其已安顿于道。"},{id:"xwg_monkey_xianqiao",term:"见巧乎王",pinyin:"xiàn qiǎo hū wáng",meaning:"向王显现技巧，见联系现理解，可读 xiàn。与后文伐巧相接，但不必把所有能力展示都归为傲慢。"},{id:"xwg_monkey_minji",term:"敏给搏捷矢",pinyin:"mǐn jǐ bó jié shǐ",meaning:"敏捷接取、搏取来矢等。给在敏捷义读 jǐ；捷的具体句法有讨论空间。按寓言情节理解，不作为现实接箭技能。"},{id:"xwg_monkey_xiangzhe",term:"相者趋射之",pinyin:"xiàng zhě qū shè zhī",meaning:"辅助、随从者奉命趋射。相者、趋的具体解释依注本处理，不必仅定为现代意义的助手同时齐射。"},{id:"xwg_monkey_faqiao",term:"伐其巧",pinyin:"fá qí qiǎo",meaning:"夸耀自己的灵巧。伐在此指夸耀、自伐。"},{id:"xwg_monkey_ji2",term:"殛",pinyin:"jí",meaning:"诛杀、杀死。猴因夸巧而死是吴王给出的解释，不能据此免除射杀者的行为责任。"},{id:"xwg_monkey_chuse",term:"锄其色",pinyin:"chú qí sè",meaning:"去除骄矜外显之态。色不只等同才能，不要求将全部能力抹去。"},{id:"xwg_monkey_quleshixian",term:"去乐辞显",pinyin:"qù lè cí xiǎn",meaning:"离开享乐、辞去显达。与锄其色并列，写颜不疑的转变。"},{id:"xwg_monkey_yanbuyi",term:"颜不疑",pinyin:"yán bù yí",meaning:"篇中求师者，吴王之友。具体历史身份不在此坐实。"},{id:"xwg_monkey_dongwu",term:"董梧",pinyin:"dǒng wú",meaning:"颜不疑之师。不直接为其设定确定境界。"}],A=[{id:"xwg_sorrow_s1",label:"隐几仰嘘：形心之问",sentences:[[{text:"南伯子綦",glossary:"xwg_sorrow_nanbo"},{text:"隐几",glossary:"xwg_sorrow_yinji"},"而坐，仰天而",{text:"嘘",glossary:"xwg_sorrow_xu"},"。"],[{text:"颜成子",glossary:"xwg_sorrow_yancheng"},"入见曰：「夫子，物之尤也。形固可使若",{text:"槁骸",glossary:"xwg_sorrow_gaohai"},"，心固可使若",{text:"死灰",glossary:"xwg_sorrow_sihui"},"乎？」"]]},{id:"xwg_sorrow_s2",label:"田禾一睹：众人三贺",sentences:[["曰：「吾尝居山穴之中矣。当是时也，",{text:"田禾一睹我而齐国之众三贺之",glossary:"xwg_sorrow_tianhe"},"。"]]},{id:"xwg_sorrow_s3",label:"由彼及己：知、卖与鬻",sentences:[[{text:"我必先之",glossary:"xwg_sorrow_woxian"},"，彼故知之；",{text:"我必卖之",glossary:"xwg_sorrow_womai"},"，",{text:"彼故鬻之",glossary:"xwg_sorrow_biyu"},"。"],["若我而不有之，彼恶得而知之？若我而不卖之，彼恶得而鬻之？"]]},{id:"xwg_sorrow_s4",label:"悲的层层回看",sentences:[["嗟乎！我",{text:"悲人",glossary:"xwg_sorrow_beiren"},"之自丧者；吾又",{text:"悲夫悲人者",glossary:"xwg_sorrow_beibeizhe"},"；"],["吾又悲夫悲人之悲者；",{text:"其后而日远",glossary:"xwg_sorrow_riyuan"},"矣！」"]]}],S=[{id:"xwg_sorrow_nanbo",term:"南伯子綦",pinyin:"nán bó zǐ qí",meaning:"篇中人物。与《齐物论》南郭子綦场景可对读，名称与情节不完全相同，不径直确定同一历史身份。"},{id:"xwg_sorrow_yancheng",term:"颜成子",pinyin:"yán chéng zǐ",meaning:"本篇的入见者。与《齐物论》颜成子游可对读，不作同一历史身份的确定。"},{id:"xwg_sorrow_yinji",term:"隐几",pinyin:"yǐn jī",meaning:"倚靠几案。几读 jī。不把外在姿态作为判断得道与否的可靠技术。"},{id:"xwg_sorrow_xu",term:"嘘",pinyin:"xū",meaning:"呼气长叹。与隐几并列，写其形貌。"},{id:"xwg_sorrow_gaohai",term:"槁骸",pinyin:"gǎo hái",meaning:"枯槁的形骸。不能作死亡、失去感受或疾病状态的修养要求。"},{id:"xwg_sorrow_sihui",term:"死灰",pinyin:"sǐ huī",meaning:"熄灭的灰烬。与槁骸并列，是心境的譬喻。"},{id:"xwg_sorrow_tianhe",term:"田禾一睹我而齐国之众三贺之",pinyin:"tián hé yī dǔ wǒ ér qí guó zhī zhòng sān hè zhī",meaning:"田禾与子綦相见，引起众人庆贺。田禾常联系田和理解；原文没有明说他因这次相见获得重用，不补写该因果。"},{id:"xwg_sorrow_woxian",term:"我必先之",pinyin:"wǒ bì xiān zhī",meaning:"先、卖、鬻的具体关系有解释空间。可联系自身有所显露理解，不将自省改成被利用者应负全部责任。"},{id:"xwg_sorrow_womai",term:"我必卖之",pinyin:"wǒ bì mài zhī",meaning:"卖：炫示、显露。原文以反问层层推进：若不显露，他人无从得知。"},{id:"xwg_sorrow_biyu",term:"彼故鬻之",pinyin:"bǐ gù yù zhī",meaning:"鬻：卖。与「我必卖之」相对，写他人因己之显露而传播利用。"},{id:"xwg_sorrow_beiren",term:"悲人",pinyin:"bēi rén",meaning:"悲他人之自丧。原文由此转入对悲者自身的回看。"},{id:"xwg_sorrow_beibeizhe",term:"悲夫悲人者",pinyin:"bēi fū bēi rén zhě",meaning:"转而回看悲人者及其悲。可联系悲的反思与递归，不直接断言所有悲悯都傲慢。"},{id:"xwg_sorrow_riyuan",term:"其后而日远",pinyin:"qí hòu ér rì yuǎn",meaning:"后续推展、愈加远去等，所远对象与递进关系有解释空间。不将其计算成每加一层悲便降低一级境界。"}],C=[{id:"xwg_great_s1",label:"楚王设酒：宜僚发言",sentences:[["仲尼之楚，楚王",{text:"觞",glossary:"xwg_great_shang"},"之。孙叔敖执",{text:"爵",glossary:"xwg_great_jue"},"而立。"],["市南宜僚",{text:"受酒而祭",glossary:"xwg_great_shoujiu"},"，曰：「",{text:"古之人乎！于此言已",glossary:"xwg_great_guren"},"。」"]]},{id:"xwg_great_s2",label:"不言之言：弄丸与投兵",sentences:[["曰：「丘也闻不言之言矣，未之尝言，于此乎言之："],["市南宜僚",{text:"弄丸",glossary:"xwg_great_nongwan"},"而两家之难解；孙叔敖",{text:"甘寝秉羽",glossary:"xwg_great_ganqin"},"而郢人投兵；",{text:"丘愿有喙三尺",glossary:"xwg_great_hui"},"。」"]]},{id:"xwg_great_s3",label:"道与言知：总归与止息",sentences:[["彼之谓",{text:"不道之道",glossary:"xwg_great_budao"},"，此之谓",{text:"不言之辩",glossary:"xwg_great_buyan"},"。"],["故",{text:"德总乎道之所一",glossary:"xwg_great_zongxiu"},"，而",{text:"言休乎知之所不知",glossary:"xwg_great_yanxiu"},"，至矣。"],["道之所一者，德不能同也。知之所不能知者，辩不能举也。",{text:"名若儒墨而凶",glossary:"xwg_great_ming"},"矣。"]]},{id:"xwg_great_s4",label:"海与圣人：并包而不据名",sentences:[["故海不辞东流，大之至也。圣人并包天地，泽及天下，而不知其谁氏。"],["是故生",{text:"无爵",glossary:"xwg_great_wujue"},"，死",{text:"无谥",glossary:"xwg_great_wushi"},"，",{text:"实不聚",glossary:"xwg_great_shibuju"},"，",{text:"名不立",glossary:"xwg_great_mingbuli"},"，此之谓大人。"]]},{id:"xwg_great_s5",label:"善言不尽贤：刻意为大",sentences:[["狗不以善吠为良，人不以善言为贤，而况为大乎！"],["夫为大不足以为大，而况为德乎！"]]},{id:"xwg_great_s6",label:"大备与反己：不以物易己",sentences:[["夫",{text:"大备",glossary:"xwg_great_dabei"},"矣，莫若天地。然奚求焉，而大备矣！"],["知大备者，",{text:"无求",glossary:"xwg_great_wuqiu"},"，",{text:"无失",glossary:"xwg_great_wushi2"},"，",{text:"无弃",glossary:"xwg_great_wuqi"},"，",{text:"不以物易己",glossary:"xwg_great_buyiwuyiji"},"也。"],[{text:"反己而不穷",glossary:"xwg_great_fanji2"},"，",{text:"循古而不摩",glossary:"xwg_great_xungu"},"，大人之诚！"]]}],V=[{id:"xwg_great_shang",term:"觞",pinyin:"shāng",meaning:"在此用作以酒款待。楚王觞之，即以酒招待孔子。"},{id:"xwg_great_jue",term:"爵",pinyin:"jué",meaning:"酒器。孙叔敖执爵而立；此处为酒器，与后文爵位之爵不同。"},{id:"xwg_great_shoujiu",term:"受酒而祭",pinyin:"shòu jiǔ ér jì",meaning:"可联系饮酒前的祭酒礼理解，不必另补完整祭祀典礼。"},{id:"xwg_great_guren",term:"古之人乎！于此言已",pinyin:"gǔ zhī rén hū! yú cǐ yán yǐ",meaning:"句读、语气有解释空间，可联系对古人之风的感叹与发言邀请等理解。不定为古人的全部道已经在此说尽。"},{id:"xwg_great_nongwan",term:"弄丸",pinyin:"nòng wán",meaning:"操作丸球。寓言描写，不证明人物此前没有任何治理行动。"},{id:"xwg_great_ganqin",term:"甘寝秉羽",pinyin:"gān qǐn bǐng yǔ",meaning:"安卧持羽。羽所指与相关典故有不同解释，不必定为现代羽扇。"},{id:"xwg_great_hui",term:"丘愿有喙三尺",pinyin:"qiū yuàn yǒu huì sān chǐ",meaning:"孔子自称愿有三尺之喙。喙：嘴。反常语气与其所指有讨论空间，不直接定为孔子承认自己全部言辞无用。"},{id:"xwg_great_budao",term:"不道之道",pinyin:"bù dào zhī dào",meaning:"道有说、言说等动词义，以不靠常规言说而有表达效果作反常表述。"},{id:"xwg_great_buyan",term:"不言之辩",pinyin:"bù yán zhī biàn",meaning:"与不道之道并列。不等于任何沉默都比说明更正确。"},{id:"xwg_great_zongxiu",term:"德总乎道之所一",pinyin:"dé zǒng hū dào zhī suǒ yī",meaning:"德归总于道之所一。总、同等关系有解释空间，不立即建成所有人的德全相同的理论。"},{id:"xwg_great_yanxiu",term:"言休乎知之所不知",pinyin:"yán xiū hū zhī zhī suǒ bù zhī",meaning:"言在知不能穷尽处止息。与「辩不能举」相接，说言说有其边界。"},{id:"xwg_great_ming",term:"名若儒墨而凶",pinyin:"míng ruò rú mò ér xiōng",meaning:"将儒墨之名与争立、分争风险相接。不能只按学派名称判断任何人有害，须与前文争是、言知限度连读。"},{id:"xwg_great_wujue",term:"无爵",pinyin:"wú jué",meaning:"生时无爵位。爵此处指爵位，与开头酒器不同。"},{id:"xwg_great_wushi",term:"无谥",pinyin:"wú shì",meaning:"死后无称号。谥为死后所加之称。"},{id:"xwg_great_shibuju",term:"实不聚",pinyin:"shí bù jù",meaning:"实有财货、实有所得等解释。不以有无资产直接裁定人格高下。"},{id:"xwg_great_mingbuli",term:"名不立",pinyin:"míng bù lì",meaning:"不立名。与实不聚并列，写「大人」不以名位自立。"},{id:"xwg_great_dabei",term:"大备",pinyin:"dà bèi",meaning:"广大完备的理想表达。不是保证现实没有损失、生活不需资源或支持。"},{id:"xwg_great_wuqiu",term:"无求",pinyin:"wú qiú",meaning:"不强求。与无失、无弃并列，是「知大备」者的态度。"},{id:"xwg_great_wushi2",term:"无失",pinyin:"wú shī",meaning:"不陷于得失。与无求、无弃并列。"},{id:"xwg_great_wuqi",term:"无弃",pinyin:"wú qì",meaning:"不弃取。三者合看，写不以外物增损自身。"},{id:"xwg_great_buyiwuyiji",term:"不以物易己",pinyin:"bù yǐ wù yì jǐ",meaning:"不以外物换失自身。不等于不能学习改变。"},{id:"xwg_great_fanji2",term:"反己而不穷",pinyin:"fǎn jǐ ér bù qióng",meaning:"返回自身而不竭。与「反己」之反省相接。"},{id:"xwg_great_xungu",term:"循古而不摩",pinyin:"xún gǔ ér bù mó",meaning:"循古而不磨损。循古不必作机械复古。"}],I=[{id:"xwg_fortune_s1",label:"相八子：九方歅称梱为祥",sentences:[["子綦有八子，陈诸前，召",{text:"九方歅",glossary:"xwg_fortune_jiufang"},"曰：「为我相吾子，孰为祥。」"],["九方歅曰：「",{text:"梱",glossary:"xwg_fortune_kun"},"也为祥。」子綦",{text:"瞿然",glossary:"xwg_fortune_juran"},"喜曰：「奚若？」"]]},{id:"xwg_fortune_s2",label:"同食之言：由喜转涕",sentences:[["曰：「梱也，将与国君同食以终其身。」"],["子綦",{text:"索然出涕",glossary:"xwg_fortune_suoran"},"曰：「吾子何为以至于是极也？」"]]},{id:"xwg_fortune_s3",label:"九方歅评父子：御福与不祥",sentences:[["九方歅曰：「夫与国君同食，",{text:"泽及三族",glossary:"xwg_fortune_sanzu"},"，而况父母乎！"],["今夫子闻之而泣，是",{text:"御福",glossary:"xwg_fortune_yufu"},"也。子则祥矣，父则不祥。」"]]},{id:"xwg_fortune_s4",label:"所自来之问：不只看酒肉",sentences:[["子綦曰：「歅，汝何足以识之。而梱祥邪？尽于酒肉，入于鼻口矣，而何足以知其所自来！"],["吾未尝为牧而",{text:"牂",glossary:"xwg_fortune_zang2"},"生于",{text:"奥",glossary:"xwg_fortune_ao"},"，未尝好",{text:"田",glossary:"xwg_fortune_tian"},"而鹑生于",{text:"宎",glossary:"xwg_fortune_yao"},"，若勿怪，何邪？"]]},{id:"xwg_fortune_s5",label:"父子之游：不以物相撄",sentences:[["吾所与吾子游者，游于天地，吾与之邀乐于天，吾与之邀食于地。"],["吾不与之为事，不与之为谋，不与之为怪。"],["吾与之乘天地之诚而不以物与之相撄，吾与之",{text:"一委蛇",glossary:"xwg_fortune_yiweiyi"},"而",{text:"不与之为事所宜",glossary:"xwg_fortune_buweishi"},"。"]]},{id:"xwg_fortune_s6",label:"世俗之偿：并非父子之罪",sentences:[["今也然有世俗之偿焉？凡有",{text:"怪征",glossary:"xwg_fortune_guizheng"},"者必有",{text:"怪行",glossary:"xwg_fortune_guixing"},"。"],["殆乎！非我与吾子之罪，",{text:"几天与之",glossary:"xwg_fortune_jitian"},"也！吾是以泣也。」"]]},{id:"xwg_fortune_s7",label:"盗劫、刖足与鬻卖",sentences:[["无几何而使梱之于燕，盗得之于道，全而鬻之则难，不若刖之则易。"],["于是乎",{text:"刖而鬻之",glossary:"xwg_fortune_yueyu"},"于齐，适当",{text:"渠公之街",glossary:"xwg_fortune_qugong"},"，",{text:"然身食肉而终",glossary:"xwg_fortune_shirou"},"。"]]}],D=[{id:"xwg_fortune_jiufang",term:"九方歅",pinyin:"jiǔ fāng yīn",meaning:"篇中的相者。来稿「九方囗」按上下文统一为九方歅；人物能力按寓言理解，不证明现实相术可靠。"},{id:"xwg_fortune_kun",term:"梱",pinyin:"kǔn",meaning:"子綦之子，被相为「祥」者。保留来稿字形。"},{id:"xwg_fortune_juran",term:"瞿然",pinyin:"jù rán",meaning:"惊动、惊喜之状。子綦闻「祥」而喜。"},{id:"xwg_fortune_suoran",term:"索然出涕",pinyin:"suǒ rán chū tì",meaning:"与情绪转变而落泪相接。具体神态训释有差异，不把父亲的哭直接判为挡住现实福气。"},{id:"xwg_fortune_sanzu",term:"泽及三族",pinyin:"zé jí sān zú",meaning:"三族的范围有不同古义。九方歅以此说「祥」。"},{id:"xwg_fortune_yufu",term:"御福",pinyin:"yù fú",meaning:"九方歅对子綦哭泣的评价。属于人物判断，不作为哭泣影响运势的事实。"},{id:"xwg_fortune_zang2",term:"牂",pinyin:"zāng",meaning:"母羊。原文「未尝为牧而牂生于奥」，以未从事相关活动却出现相关物作反常譬喻。"},{id:"xwg_fortune_ao",term:"奥",pinyin:"ào",meaning:"室内深处或角落，解释有差异。"},{id:"xwg_fortune_tian",term:"田",pinyin:"tián",meaning:"联系畋猎理解。原文「未尝好田而鹑生于宎」。"},{id:"xwg_fortune_yao",term:"宎",pinyin:"yǎo",meaning:"室内角落，与奥同类。不必当作实录。"},{id:"xwg_fortune_yiweiyi",term:"一委蛇",pinyin:"yī wēi yí",meaning:"相与随顺。句法有解释空间。"},{id:"xwg_fortune_buweishi",term:"不与之为事所宜",pinyin:"bù yǔ zhī wéi shì suǒ yí",meaning:"不强定事务之宜。不等于父母不应教育、照料或制定必要安全安排。"},{id:"xwg_fortune_guizheng",term:"怪征",pinyin:"guài zhēng",meaning:"异样征兆。子綦由此推断「必有怪行」。"},{id:"xwg_fortune_guixing",term:"怪行",pinyin:"guài xíng",meaning:"异常遭际或行为。与怪征相接。"},{id:"xwg_fortune_jitian",term:"几天与之",pinyin:"jī tiān yǔ zhī",meaning:"几可联系恐怕理解。是子綦的判断，不作为预知命运的规律；原文明说非父子之罪。"},{id:"xwg_fortune_yueyu",term:"刖而鬻之",pinyin:"yuè ér yù zhī",meaning:"砍去足部再出售。刖、鬻由盗贼实施，不能把故事整理为梱因自身追逐富贵而应受伤害。"},{id:"xwg_fortune_qugong",term:"渠公之街",pinyin:"qú gōng zhī jiē",meaning:"街的字形及解释有讨论空间，有联系衢公、阉者服役等校释。不能仅按街道补成在那里吃肉。"},{id:"xwg_fortune_shirou",term:"然身食肉而终",pinyin:"rán shēn shí ròu ér zhōng",meaning:"然身的字形及解释有讨论空间。不把末句扩大为实际与君主同席。"}],R=[{id:"xwg_benevolence_s1",label:"啮缺问去处：许由将逃尧",sentences:[[{text:"啮缺",glossary:"xwg_benevolence_nieque"},"遇",{text:"许由",glossary:"xwg_benevolence_xuyou"},"曰：「子将奚之？」曰：「将逃尧。」曰：「奚谓邪？」"]]},{id:"xwg_benevolence_s2",label:"仁的反常警告：后世人相食",sentences:[["曰：「夫尧",{text:"畜畜然仁",glossary:"xwg_benevolence_chuchu"},"，吾恐其为天下笑。后世其",{text:"人与人相食",glossary:"xwg_benevolence_renxiangshi"},"与！"]]},{id:"xwg_benevolence_s3",label:"聚散的条件：爱、利、誉与所恶",sentences:[["夫民不难聚也，爱之则亲，利之则至，誉之则劝，致其所恶则散。"]]},{id:"xwg_benevolence_s4",label:"仁义之名：利用者与无诚",sentences:[["爱利出乎仁义，",{text:"捐仁义者寡，利仁义者众",glossary:"xwg_benevolence_juan"},"。"],["夫仁义之行，唯且无诚，且",{text:"假乎禽贪者器",glossary:"xwg_benevolence_qintan"},"。"]]},{id:"xwg_benevolence_s5",label:"断制与利害：不只看贤人之利",sentences:[["是以一人之断制天下，譬之犹",{text:"一覕",glossary:"xwg_benevolence_pie"},"也。"],["夫尧知贤人之利天下也，而不知其",{text:"贼天下",glossary:"xwg_benevolence_zeitianxia"},"也。夫唯",{text:"外乎贤者",glossary:"xwg_benevolence_wai"},"知之矣。」"]]}],G=[{id:"xwg_benevolence_nieque",term:"啮缺",pinyin:"niè quē",meaning:"《庄子》中多次出现的人物。不仅凭本段坐实其历史身份或宣称全为作者虚构。"},{id:"xwg_benevolence_xuyou",term:"许由",pinyin:"xǔ yóu",meaning:"《庄子》中多次出现的人物，亦见相关古代传说。本段由他回答逃尧之故。"},{id:"xwg_benevolence_chuchu",term:"畜畜然仁",pinyin:"chù chù rán rén",meaning:"勤谨、殷勤行仁等，音义依注本统一。反常批评指向行仁方式及其后果，不由此认定关怀本身毫无价值。"},{id:"xwg_benevolence_renxiangshi",term:"人与人相食",pinyin:"rén yǔ rén xiāng shí",meaning:"以极端后果警告竞争、权力与利用的危险。是许由的激烈判断，不是已验证的精确历史预报。"},{id:"xwg_benevolence_juan",term:"捐仁义者寡，利仁义者众",pinyin:"juān rén yì zhě guǎ, lì rén yì zhě zhòng",meaning:"捐有弃、舍等解释，亦有不同训法；利联系借仁义获利理解。不能将多数这一概括当作现代统计事实。"},{id:"xwg_benevolence_qintan",term:"假乎禽贪者器",pinyin:"jiǎ hū qín tān zhě qì",meaning:"仁义可能被借为禽贪者的工具。禽贪的具体训释有差异，可把握借仁义之名满足贪求的批评。"},{id:"xwg_benevolence_pie",term:"一覕",pinyin:"yī piē",meaning:"覕涉及短见、片刻之见等训释，音义有讨论空间。不直接等同现代瞥一眼的唯一字义；上下文批评一人断制的局限。"},{id:"xwg_benevolence_zeitianxia",term:"贼天下",pinyin:"zéi tiān xià",meaning:"贼为损害。原文「不知其贼天下也」，指贤者之利亦可能为害。"},{id:"xwg_benevolence_wai",term:"外乎贤者",pinyin:"wài hū xián zhě",meaning:"可联系不受贤名框架拘限者理解。不能据此把贤者整体认定为应被排除的人群。"}],N=[{id:"xwg_confinement_s1",label:"三类名称：暖姝、濡需、卷娄",sentences:[["有",{text:"暖姝",glossary:"xwg_confinement_nuanshu"},"者，有",{text:"濡需",glossary:"xwg_confinement_ruxu"},"者，有卷娄者。"]]},{id:"xwg_confinement_s2",label:"暖姝：学一家之言便自以为足",sentences:[["所谓暖姝者，学一先生之言，则暖暖姝姝而",{text:"私自说",glossary:"xwg_confinement_shuo"},"也，"],["自以为足矣，而",{text:"未知未始有物",glossary:"xwg_confinement_weishi"},"也。是以谓暖姝者也。"]]},{id:"xwg_confinement_s3",label:"濡需：豕虱以所居为广大安稳",sentences:[["濡需者，",{text:"豕虱",glossary:"xwg_confinement_shishi"},"是也，择疏",{text:"鬣",glossary:"xwg_confinement_lie"},"长毛，自以为广宫大囿。"],[{text:"奎蹄曲隈",glossary:"xwg_confinement_kuiti"},"，",{text:"乳间股脚",glossary:"xwg_confinement_rujian"},"，自以为安室利处。"]]},{id:"xwg_confinement_s4",label:"所依之危：与豕俱焦",sentences:[["不知屠者之一旦",{text:"鼓臂布草操烟火",glossary:"xwg_confinement_gubi"},"，而己",{text:"与豕俱焦",glossary:"xwg_confinement_jujiao"},"也。"],["此",{text:"以域进",glossary:"xwg_confinement_yujin"},"，此",{text:"以域退",glossary:"xwg_confinement_yutui"},"，此其所谓濡需者也。"]]}],E=[{id:"xwg_confinement_nuanshu",term:"暖姝",pinyin:"nuǎn shū",meaning:"自得、自满之状。原文具体批评学一家之言便自以为足，不把一切学习后的喜悦都判为空虚。"},{id:"xwg_confinement_shuo",term:"私自说",pinyin:"sī zì yuè",meaning:"私下自悦、自我满足。说联系悦理解，读 yuè。"},{id:"xwg_confinement_weishi",term:"未知未始有物",pinyin:"wèi zhī wèi shǐ yǒu wù",meaning:"涉及未始有物的认识，句法与哲学意义有解释空间。不能只定为此前学习没有得到任何东西，也不等于所有知识皆空。"},{id:"xwg_confinement_ruxu",term:"濡需",pinyin:"rú xū",meaning:"沾滞、依附等。后文以豕虱的居处说明，不仅是一般意义的懒惰或不努力。"},{id:"xwg_confinement_shishi",term:"豕虱",pinyin:"shǐ shī",meaning:"猪身上的虱子。以所依动物的身体比作宫室园囿，形成尺度上的反常。"},{id:"xwg_confinement_lie",term:"鬣",pinyin:"liè",meaning:"鬃毛。原文「择疏鬣长毛」，与豕虱并列描写其择处。"},{id:"xwg_confinement_kuiti",term:"奎蹄曲隈",pinyin:"kuí tí qū wēi",meaning:"描写猪体部位与曲折处，具体字形、断句与名物解释须依底本统一。不将全部词语强定为现代解剖名称。"},{id:"xwg_confinement_rujian",term:"乳间股脚",pinyin:"rǔ jiān gǔ jiǎo",meaning:"与奎蹄曲隈并列，写虱自以为安稳的所在。"},{id:"xwg_confinement_gubi",term:"鼓臂布草操烟火",pinyin:"gǔ bì bù cǎo cāo yān huǒ",meaning:"屠者操作草、火。写依附条件一变，局部位置的调整即难保全。"},{id:"xwg_confinement_jujiao",term:"与豕俱焦",pinyin:"yǔ shǐ jù jiāo",meaning:"所依的猪与虱一同受毁。不作现实屠宰流程的完整说明。"},{id:"xwg_confinement_yujin",term:"以域进",pinyin:"yǐ yù jìn",meaning:"在同一局限范围内「进」。可反省选择共享的前提，不证明人永远无法改变处境。"},{id:"xwg_confinement_yutui",term:"以域退",pinyin:"yǐ yù tuì",meaning:"在同一局限范围内「退」。与以域进连读：进退看似有变化，范围本身未受检查。"}],B=[{id:"xwg_continuation_s1",label:"卷娄：舜与众人趋附的节引",sentences:[[{text:"卷娄",glossary:"xwg_continuation_juanlou"},"者，舜也。羊肉不慕蚁，蚁慕羊肉，羊肉膻也。"],["舜有",{text:"膻行",glossary:"xwg_continuation_shan"},"，百姓悦之。"]]},{id:"xwg_continuation_s2",label:"卷娄：不能休归的节引",sentences:[["年齿长矣，聪明衰矣，而",{text:"不得休归",glossary:"xwg_continuation_xiugui"},"，所谓卷娄者也。"]]},{id:"xwg_continuation_s3",label:"真人：抱德炀和的节引",sentences:[["故",{text:"无所甚亲",glossary:"xwg_continuation_wushenqin"},"，",{text:"无所甚疏",glossary:"xwg_continuation_wushenshu"},"，",{text:"抱德炀和",glossary:"xwg_continuation_yanghe"},"以顺天下，此谓真人。"]]}],F=[{id:"xwg_continuation_juanlou",term:"卷娄",pinyin:"quán lóu",meaning:"本段借舜说明牵累、不得休归等处境，具体音义依注本统一。不只按外形理解成猥琐，也不作人格辱骂。"},{id:"xwg_continuation_shan",term:"膻行",pinyin:"shān xíng",meaning:"以羊肉之膻吸引蚁，类比舜之行吸引众人，带有鲜明的反常与讽刺意味。不等于将舜简单定为道德恶人。"},{id:"xwg_continuation_xiugui",term:"不得休归",pinyin:"bù dé xiū guī",meaning:"不能休息、返回，提示社会期待与所承担的位置可能形成牵累。"},{id:"xwg_continuation_yanghe",term:"抱德炀和",pinyin:"bào dé yáng hé",meaning:"保有德、养护和等，炀的具体训释依注本处理。不能按现代常见贬义直接理解为毁坏和谐。"},{id:"xwg_continuation_wushenqin",term:"无所甚亲",pinyin:"wú suǒ shèn qīn",meaning:"不过分执于亲。须与上下文连读，不等于取消所有亲密关系。"},{id:"xwg_continuation_wushenshu",term:"无所甚疏",pinyin:"wú suǒ shèn shū",meaning:"不过分执于疏。也不要求对侵害者保持无边界的接近。"}];return(l,n)=>{const H=o("DaoReadingPrelude"),s=o("DaoTextReading"),r=o("DaoKeywordCards"),g=o("DaoLineGuide");return L(),M("div",null,[n[0]||(n[0]=t("",10)),a(H,{title:"先读前四段：从慰劳君主，到去害与不囿于物",summary:"徐无鬼以欲望、相狗相马和荒处思人的譬喻回应魏武侯，随后直指苦民养己与借仁义胜人的危险；牧马童子将治理转向去除妨害，第四段再描写各类人物如何被所业、所好与名势圈住。",points:[{label:"先看",text:"武侯如何理解山林生活与来访？徐无鬼为何反过来慰劳君主？"},{label:"再问",text:"爱民、偃兵与胜人之间是否存在张力？去害需要怎样的实际辨析？"},{label:"最后",text:"学习、劳动与技艺何时成为囿？不被圈住是否等于停止这些活动？"}],hint:"全篇十四段均已整理：前四段立起欲望、苦民养己、去害与囿于物的问题，五至八段转入判断尺度、争辩与关系，九至十三段落到显巧、显名、言说边界与祥、仁义，第十四段收在自以为足与所依之域；文末栏目覆盖全篇。"}),n[1]||(n[1]=e("h2",{id:"一、徐无鬼见武侯·相狗相马与真人之言",tabindex:"-1"},[i("一、徐无鬼见武侯·相狗相马与真人之言 "),e("a",{class:"header-anchor",href:"#一、徐无鬼见武侯·相狗相马与真人之言","aria-label":'Permalink to "一、徐无鬼见武侯·相狗相马与真人之言"'},"​")],-1)),n[2]||(n[2]=e("h3",{id:"原文",tabindex:"-1"},[i("原文 "),e("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:J(c),glossary:d,"default-mode":"classic","aria-label":"徐无鬼·初见武侯 原文"},null,8,["sections"]),n[3]||(n[3]=e("blockquote",null,[e("p",null,"**阅读说明：**相狗有下、中、上三种品质；相马主要对举国马与天下马，不宜标成原文明列的相马三等。"),e("p",null,"原文没有说武侯就是天下马，也没有明确把若亡其一解释为放下所有目标。")],-1)),n[4]||(n[4]=e("h3",{id:"生僻字词",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"女商",pinyin:["rǔ","shāng"],meaning:"篇中的引荐者。"},{term:"耆欲",pinyin:["shì","yù"],meaning:"嗜欲，耆联系嗜理解，音读依注本统一。"},{term:"黜",pinyin:["chù"],meaning:"压退、排除。"},{term:"相",pinyin:["xiàng"],meaning:"观察、鉴别。"},{term:"中绳",pinyin:["zhòng","shéng"],meaning:"符合绳墨，中读 zhòng。"},{term:"卹",pinyin:["xù"],meaning:"忧、忧恤等。"},{term:"超轶",pinyin:["chāo","yì"],meaning:"超越、疾驰超过。"},{term:"期年",pinyin:["jī","nián"],meaning:"满一年。"},{term:"藜藋",pinyin:["lí","diào"],meaning:"荒草。"},{term:"跫然",pinyin:["qióng","rán"],meaning:"足音之状。"},{term:"謦欬",pinyin:["qǐng","kài"],meaning:"咳声，借写人在近旁的声音。"}]}),n[5]||(n[5]=e("h3",{id:"核心句引读",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"不只检查欲望多少，也检查与欲望相处的方式",subtitle:"真人之言的稀缺，不等于所有典籍与谋议都没有价值。",lines:[{text:"我则劳于君，君有何劳于我！",tone:"反转",guide:"武侯预设隐者因山林劳苦而求见，徐无鬼反过来慰劳君主，改变了谁优谁困的关系。不能据此认定山林毫无劳苦、宫廷只有痛苦；故事首先拆开地位与生命安顿必然一致的想象。"},{text:"盈耆欲……性命之情病矣；黜耆欲……耳目病矣。",tone:"两面",guide:"满足欲望并不断增长好恶，与强行压制牵制欲望，都可能造成受损。不能因此宣布任何满足与节制都有害，也不证明调节全无作用。重点可放在放任和强压的两极，而非要求取消全部愿望。"},{text:"上之质，若亡其一。",tone:"神态",guide:"若有所失的描写形成反常的品评，具体所失为何并未明言。可以反省高下是否能只从外显目标辨认，却不必定为最高品质就是完全无目标。狗的品评也不是普遍的人格等级表。"},{text:"是国马也，而未若天下马也。",tone:"尺度",guide:"符合规矩尺度仍被承认为国马，说明标准有其识别作用；天下马则使评价超出这些可列举条件。不能把对标准充分性的限制改成一切标准都错误，更不能把超轶绝尘解释成超越宇宙。"},{text:"武侯大悦而笑。",tone:"反应",guide:"武侯的笑是明确情节，笑的全部原因却未直接说出。徐无鬼后文用久离人群而闻足音的比喻解释，不宜另补武侯被认作天下马、终于有人看见其最高境界。被触动也不保证已经改变治理。"},{text:"去人滋久，思人滋深。",tone:"相接",guide:"流亡与荒处的故事写人对熟悉声音、真实相接的渴望。见似人者可联系像故国之人者理解，不宜扩大成任何人形物体。这个比喻也不等于孤独者必定离道。"},{text:"莫以真人之言謦欬吾君之侧乎！",tone:"言说",guide:"将真实言说比作近旁人的咳声，突出不是靠典籍、功劳和说进技巧就能保证相接。謦欬不是规定真言必须轻声、短句；经典也不因此全部变成虚假。需要分辨言说如何发生，而非按音量与题材判断真假。"}]}),n[6]||(n[6]=t("",6)),a(s,{sections:u,glossary:x,"default-mode":"classic","aria-label":"徐无鬼·再见武侯与治理 原文"}),n[7]||(n[7]=e("blockquote",null,[e("p",null,"**文字说明：**无盛鹤列、无徒骥、无藏逆及无以巧、谋、战胜人，共六个「无」。"),e("p",null,"「君若勿已矣」「夫民死已脱矣」等存在解释空间，不将来稿白话作为唯一释义。")],-1)),n[8]||(n[8]=e("h3",{id:"生僻字词-1",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"芧",pinyin:["xù"],meaning:"橡实等。"},{term:"干",pinyin:["gān"],meaning:"求取。"},{term:"万乘",pinyin:["wàn","shèng"],meaning:"以兵车规模指大国君主地位。"},{term:"偃兵",pinyin:["yǎn","bīng"],meaning:"止兵、息兵。"},{term:"殆",pinyin:["dài"],meaning:"恐怕、危险等，依句意分辨。"},{term:"丽谯",pinyin:["lì","qiáo"],meaning:"楼观、城楼等。"},{term:"锱坛",pinyin:["zī","tán"],meaning:"宫室名物的疑难用语，不直接定为祭坛。"},{term:"撄",pinyin:["yīng"],meaning:"扰动、侵扰、纠缠。"},{term:"恶乎",pinyin:["wū","hū"],meaning:"哪里、何处，恶读 wū。"}]}),n[9]||(n[9]=e("h3",{id:"核心句引读-1",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"关怀的名义，不能代替对实际侵害的检查",subtitle:"原文批评仁义之名的力度，应与苦民养己、杀民兼地连读。",lines:[{text:"天地之养也一，登高不可以为长，居下不可以为短。",tone:"贵贱",guide:"以高低不能直接改变自身长短，松开地位与生命价值的绝对等同。不是说现实权力、资源与处境没有差异，而是不让君位自动成为苦民养己的许可。"},{text:"以苦一国之民，以养耳目鼻口。",tone:"代价",guide:"明确指向以民众受苦供养君主感官享受。后面的仁义批评不能脱离这一政治代价，泛化为所有照料与公共行动都有害。精神的和也不能只成为统治者自我舒适的目标。"},{text:"爱民，害民之始也；为义偃兵，造兵之本也。",tone:"反诘",guide:"这是直接、激烈的反常批评，不应抹平为普通善意提醒。但后文具体反对巧、谋、战胜人及杀民兼地，因而不必推出一切爱民措施必然害民。可检验的是以仁义名义继续控制、争胜与扩张的矛盾。"},{text:"君虽为仁义，几且伪哉！",tone:"名实",guide:"仁义行动可能转为造作、伪饰，说明名称不能保证实际结果。不能补成凡有目的就有执著、凡有执著便制造更大恶的无例外因果。救助、规划和必要防护仍需具体判断。"},{text:"无以巧胜人，无以谋胜人，无以战胜人。",tone:"胜人",guide:"连续限制以技巧、谋略和战争压倒他人，使批评落在支配关系上。不等于技术知识本身有错，也不等于面对侵害者必须放弃全部保护与抵抗。"},{text:"杀人之士民，兼人之土地……胜之恶乎在？",tone:"战争",guide:"追问以伤亡、兼并供养私欲的所谓胜利，其善与胜到底在哪里。不能只从统治者成果计算输赢，必须纳入被侵害者的生命与土地。该段也不为抽象自然之名免除侵害责任。"},{text:"修胸中之诚以应天地之情而勿撄。",tone:"应接",guide:"修诚与应接、勿撄相连，不是躲入内心便无需改变实际行为。若仍苦民养己，主观真诚不能自动使行动正当。内在反省应当与减少侵害共同理解。"},{text:"夫民死已脱矣，君将恶乎用夫偃兵哉！",tone:"疑难",guide:"末句牵涉死、脱与偃兵的关系，存在不同训释，应依底本校定。可以保留对百姓处境及止兵名义的严厉追问，不能赞美死亡是民众应求的解脱，也不自行补成百姓已经全部死去。"}]}),n[10]||(n[10]=t("",10)),a(s,{sections:_,glossary:m,"default-mode":"classic","aria-label":"徐无鬼·黄帝问牧马童子 原文"}),n[11]||(n[11]=e("blockquote",null,[e("p",null,[e("strong",null,"人数说明："),i("「七圣」包括黄帝及六位同行者。")]),e("p",null,"童子明确知道道路和大隗所在，不能称作没有知识、没有能力的人。")],-1)),n[12]||(n[12]=e("h3",{id:"生僻字词-2",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"大隗",pinyin:["dà","wěi"],meaning:"篇中黄帝所寻人物。"},{term:"具茨",pinyin:["jù","cí"],meaning:"山名。"},{term:"御",pinyin:["yù"],meaning:"驾车。"},{term:"骖乘",pinyin:["cān","shèng"],meaning:"陪乘、车右等。"},{term:"涂",pinyin:["tú"],meaning:"道路，联系途理解。"},{term:"瞀",pinyin:["mào"],meaning:"昏眩、昏乱等。"},{term:"痊",pinyin:["quán"],meaning:"病情好转。"},{term:"稽首",pinyin:["qǐ","shǒu"],meaning:"拜而叩首的礼节。"}]}),n[13]||(n[13]=e("h3",{id:"核心句引读-2",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"知路者不必有高位，去除妨害也可以是实际行动",subtitle:"童子的知识受到肯定，不是以无知取代知识。",lines:[{text:"七圣皆迷，无所问涂。",tone:"迷路",guide:"高位者与同行圣者仍可能迷路，提醒声望不保证掌握所有地方知识。原文没有解释迷路因分析、谋划造成，也不能由这次情节推出知识与能力普遍不能指路。"},{text:"非徒知具茨之山，又知大隗之所存。",tone:"知道",guide:"黄帝明确肯定童子有所知，故事不是不知者胜过知者的简单二分。童子的经验、熟悉与回答本身就是知识。可以反省谁的知识容易被忽略，而不是将童子称为毫无知识。"},{text:"乘日之车而游于襄城之野。",tone:"游与病",guide:"童子用病与游的故事回答治理，寓言意味丰富，但乘日之车与瞀病的确切含义有空间。不能把顺自然游行当作治疗眩晕的方法，也不能给其病补上未明说的心理病因。"},{text:"夫为天下亦若此而已。予又奚事焉！",tone:"多事",guide:"限制额外多事与妄加，不等于生活无需照料。童子还曾接受长者指引，病也只是少痊，不能把他写成完全独立于帮助与条件的全能者。"},{text:"亦去其害马者而已矣！",tone:"去害",guide:"去除妨害是本段最清楚的治理譬喻。害马者未被具体列出，训练、管制或使用不能一概宣布为害；去除危险、改进条件也需要观察和行动。更不能将这句扩大为对所谓有害人群的惩杀原则。"},{text:"再拜稽首，称天师而退。",tone:"受教",guide:"黄帝向牧马童子致敬，颠倒地位与受教资格的常见安排。可以肯定向不同处境的人学习，却不必建立卑微者天然正确、显达者必定错误的新等级。"}]}),n[14]||(n[14]=t("",7)),a(s,{sections:h,glossary:y,"default-mode":"classic","aria-label":"徐无鬼·各类人物囿于物 原文"}),n[15]||(n[15]=e("blockquote",null,[e("p",null,"**阅读说明：**本段对各类人物的描写具有概括性和批评力度，但不能直接将所有人的全部劳动、知识与关怀认定为错误。"),e("p",null,"「中民」「矜雅」「不比」「不物于易」等，宜依统一注本校定。")],-1)),n[16]||(n[16]=e("h3",{id:"生僻字词-3",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"囿",pinyin:["yòu"],meaning:"圈住、局限。"},{term:"凌谇",pinyin:["líng","suì"],meaning:"凌厉诘责等。"},{term:"宿名",pinyin:["sù","míng"],meaning:"寄托、止于名声等。"},{term:"草莱",pinyin:["cǎo","lái"],meaning:"田间草地、荒草等。"},{term:"商贾",pinyin:["shāng","gǔ"],meaning:"商人。"},{term:"劝",pinyin:["quàn"],meaning:"勤勉、受到激励。"},{term:"尤",pinyin:["yóu"],meaning:"突出、超过等。"},{term:"反",pinyin:["fǎn"],meaning:"联系返、返回理解。"}]}),n[17]||(n[17]=e("h3",{id:"核心句引读-3",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"能力可以被运用，也可能反过来圈住运用能力的人",subtitle:"所业不是原罪，不能返回与调整才是本段警告的方向。",lines:[{text:"无思虑之变则不乐……无谈说之序则不乐。",tone:"不能停",guide:"知识、辩论与诘察被写成不具备相应活动便无法安乐，揭示依附性。不能直接断言这些人不是真的喜欢活动，原文也没有证明其内在动机。可关注喜欢与离不开之间的区别。"},{text:"皆囿于物者也。",tone:"圈住",guide:"物可以是所事、所重，不只指财物。学习、议论、身份乃至名声，都可能成为圈限。主动选择与受限并非绝对分开：人可以真心选择一项活动，同时逐渐丧失停止或修正的余地。"},{text:"枯槁之士宿名。",tone:"隐与名",guide:"外在隐处朴苦也可能仍寄于名，不意味着隐居自动超脱。但不能由一类描写判断所有隐者都刻意表演；高位与隐处都需检查其所依，而不靠外貌保证自由。"},{text:"法律之士广治；礼乐之士敬容；仁义之士贵际。",tone:"规范",guide:"原文将法律、礼乐、仁义之士纳入批评，不能抹掉力度。但也不能由此取消法律保护、相互尊重与照料责任。可反省个人是否把一套所业认作全部，而不将所有规范直接判为伤害。"},{text:"庶人有旦暮之业则劝；百工有器械之巧则壮。",tone:"劳动",guide:"日常劳动与技巧使人勤勉振奋，置于全段中被反省为依附的一部分。仍不能直接说农夫、工匠和普通人不应工作。第三段牧马童子也具有实践所知，问题不只在有没有职业。"},{text:"遭时有所用，不能无为也。",tone:"时机",guide:"一遇时机与用途便不能停下，可能使生命持续被机会牵引。不能把有所用一概定为失道，也不必拒绝所有合适机会。应辨明是否仍能判断代价、拒绝不当要求并保有调整空间。"},{text:"驰其形性，潜之万物，终身不反，悲夫！",tone:"返回",guide:"形性奔逐、沉于万物而不能返回，是本段沉重收束。悲既有感叹也有批评，不必强分成纯粹悲悯、绝无责问。返回可以联系重新安顿与调整处身，不必要求人人退出社会。"}]}),n[18]||(n[18]=t("",15)),a(s,{sections:w,glossary:b,"default-mode":"classic","aria-label":"徐无鬼·公是与鲁遽调瑟 原文"}),n[19]||(n[19]=e("blockquote",null,[e("p",null,"**分段说明：**来稿末尾的惠子发言与第六段开头重复，本页只保留在第六段。"),e("p",null,"**释义说明：**五音之「角」读 jué。「未始异于声」不能反译为从不属于声音；「二十五弦皆动」按寓言理解，不作为现代声学的普遍规律。")],-1)),n[20]||(n[20]=e("h3",{id:"生僻字词-4",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"前期",pinyin:["qián","qī"],meaning:"事先约定、确定目标。"},{term:"中",pinyin:["zhòng"],meaning:"射中。"},{term:"公是",pinyin:["gōng","shì"],meaning:"共同据以认定为是的判断。"},{term:"鲁遽",pinyin:["lǔ","jù"],meaning:"寓言中的老师。"},{term:"爨",pinyin:["cuàn"],meaning:"烧火炊煮。"},{term:"废",pinyin:["fèi"],meaning:"此处联系放置理解。"},{term:"角",pinyin:["jué"],meaning:"五音之一。"},{term:"徵",pinyin:["zhǐ"],meaning:"五音之一。"},{term:"音之君",pinyin:["yīn","zhī","jūn"],meaning:"对能使众弦相应者的反常称谓。"}]}),n[21]||(n[21]=e("h3",{id:"核心句引读-4",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"自称射中之前，先问目标怎样确定",subtitle:"相应不只限于同类，但寓言并未提供一项可以直接占有的公共真理。",lines:[{text:"射者非前期而中谓之善射，天下皆羿也，可乎？",tone:"目标",guide:"若不先确定所射目标，射后再称自己射中，善射的标准便可能失去约束作用。可由此理解天下皆羿的反问：怎样才不只是各自给自己命名？具体语气有解释空间，不宜先说射中已是客观标准，再据此证明天下人都能成为羿。"},{text:"天下非有公是也，而各是其所是。",tone:"各自之是",guide:"讨论各自认可自身所是、却缺少共同尺度的处境。可以与《齐物论》的彼此是非对读，但不能据此宣布事实证据、共同规则与公共论证全无可能。争议中的各自认可，不等于所有判断都同样可靠。"},{text:"儒墨杨秉四，与夫子为五，果孰是邪？",tone:"争是",guide:"把惠子也纳入彼此争是的立场，追问各家自认正确如何保证其正确。杨、秉所指宜依注本处理。这里不是已经裁决五家全错，而是反省以自家尺度证明自家之是的方法。"},{text:"是直以阳召阳，以阴召阴，非吾所谓道也。",tone:"同类",guide:"鲁遽限制弟子由某种能力直接宣布得道的推论。同类感应可以成立，却不足以穷尽所说道。冬爨夏冰的技术未展开，不能补成用现成冰来召冷，也不必把所有同类研究和规则运用都判为无用。"},{text:"鼓宫宫动，鼓角角动，音律同矣！",tone:"相应",guide:"同音相应构成后文改调一弦的对照。可以借共鸣理解，却要区分古代寓言和现代实验。也不能机械把宫弦等同儒家、角弦等同墨家，原文没有逐项指定。"},{text:"于五音无当也，鼓之，二十五弦皆动。",tone:"贯通",guide:"不相当于通常音位，却能使众弦相应，是反常的贯通意象。它不保证任何不合标准的人都能触动所有人，也不能仅凭共鸣证明某一论说真实。寓言打开问题，不提供通用的成功技术。"},{text:"未始异于声而音之君已！",tone:"不离声",guide:"与声未始相异，却称音之君，提示贯通不必靠逃离声音世界完成。不能把它翻成完全不属于声音，再设为超越万物的特殊实体。音之君也不宜直接命名为原文已确立的真正公是。"}]}),n[22]||(n[22]=t("",21)),a(s,{sections:q,glossary:f,"default-mode":"classic","aria-label":"徐无鬼·惠子续问与疑难譬喻 原文"}),n[23]||(n[23]=e("blockquote",null,[e("p",null,"**校读说明：**本段「蹢子」「命阍不以完」「钘钟」「唐子」「寄而蹢阍」「岑」的字形、句法与所指均有讨论空间。"),e("p",null,"本页暂保留来稿原文，不把未经校定的白话解释扩写成确定故事。严格逐句翻译应在统一底本后补定。")],-1)),n[24]||(n[24]=e("h3",{id:"生僻字词-5",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"拂",pinyin:["fú"],meaning:"拂逆、抵牾。"},{term:"镇",pinyin:["zhèn"],meaning:"压制。"},{term:"蹢",pinyin:["zhí"],meaning:"本段有弃置等解释，须结合异文校定。"},{term:"阍",pinyin:["hūn"],meaning:"守门者，句中关系有争议。"},{term:"钘钟",pinyin:["xíng","zhōng"],meaning:"疑难词，不直接定为乐器。"},{term:"唐子",pinyin:["táng","zǐ"],meaning:"所指待校，不径直立为人名。"},{term:"域",pinyin:["yù"],meaning:"范围、地域。"},{term:"岑",pinyin:["cén"],meaning:"句中所指有不同解释。"},{term:"造怨",pinyin:["zào","yuàn"],meaning:"产生、造成怨恨。"}]}),n[25]||(n[25]=e("h3",{id:"核心句引读-5",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"争辩没有改变自身判断，不必等于判断已经得到证明",subtitle:"疑难字句先保留，不能靠补造情节获得看似完整的解释。",lines:[{text:"相拂以辞，相镇以声，而未始吾非也。",tone:"争与自认",guide:"言辞拂逆、声势压制，是较明确的争辩描写；未始吾非的主语与句法有解释空间。不能仅译成没人说我错，继而认定惠子客观赢得辩论。对手未令自己改变判断，与自己的判断已被证实仍有距离。"},{text:"齐人蹢子于宋者，其命阍也不以完。",tone:"疑难",guide:"蹢与完的意义、句间关系需要校读，完也可能涉及身体完整，不只是礼节完整。暂不补写弃子后找回、命令守门却礼数不足等经过。保留疑难比将不确定解释伪装成通顺故事更重要。"},{text:"其求钘钟也以束缚；其求唐子也而未始出域。",tone:"所求与所行",guide:"求、束缚与未出域提供所求和处身方式的讨论线索，但钘钟与唐子所指不宜坐实。可以追问方法是否相称，不必据此宣称用绳子寻找乐器、寻找名叫唐子的人却不出门。"},{text:"有遗类矣！",tone:"失配",guide:"可联系遗漏、类不相合或所求所行失配理解，仍需保留训释空间。现代可借此检查论证与问题是否相称，但不能只凭这一解释宣判所有辩论都找不到道。"},{text:"未始离于岑而足以造于怨也。",tone:"造怨",guide:"岑的所指有争议，不能仅按小土堆演绎格局狭小。造怨较明确地提示争斗产生怨恨：讨论即使没有澄清问题，也可能已经改变人际关系。需要区分论证效果与关系代价。"}]}),n[26]||(n[26]=t("",7)),a(s,{sections:k,glossary:z,"default-mode":"classic","aria-label":"徐无鬼·庄子过惠子墓 原文"}),n[27]||(n[27]=e("blockquote",null,[e("p",null,"**阅读说明：**这是一则高度理想化的技艺寓言，不能作为现实中用斧近身表演的指导。"),e("p",null,"「质」可联系配合、承受其技艺与言说的对象理解，再由故事引申相知，不必一开始就将它译为知己。")],-1)),n[28]||(n[28]=e("h3",{id:"生僻字词-6",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"郢",pinyin:["yǐng"],meaning:"楚都之名，郢人指郢地之人。"},{term:"垩",pinyin:["è"],meaning:"白垩、白色涂料。"},{term:"慢",pinyin:["màn"],meaning:"此处有涂污等解释。"},{term:"斫",pinyin:["zhuó"],meaning:"砍削。"},{term:"斤",pinyin:["jīn"],meaning:"斧。"},{term:"听",pinyin:["tīng"],meaning:"任、任运等，不只指听觉。"},{term:"质",pinyin:["zhì"],meaning:"配合、承受其技艺或言说的对象。"}]}),n[29]||(n[29]=e("h3",{id:"核心句引读-6",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"反省争辩，不等于否定能与自己相对而谈的人",subtitle:"关系与配合，是技艺和言说得以发生的条件。",lines:[{text:"庄子送葬，过惠子之墓。",tone:"经过",guide:"送葬途中经过惠子墓而述寓言，构成哀悼场景。原文没有明确说这场葬礼就是惠子的葬礼，也不能据此复原两人的完整生平与相交年数。"},{text:"尽垩而鼻不伤，郢人立不失容。",tone:"配合",guide:"匠石的精细操作与郢人的镇定同时呈现，不能只留下单方面技术。可由此理解信任与配合的重要性，但不必补成郢人绝无恐惧、双方已经具有完全相同的认识。"},{text:"臣则尝能斫之。虽然，臣之质死久矣！",tone:"不可替代",guide:"曾经能够完成，并不保证在另一位受术者面前还能同样完成。技艺有对象与条件，君主命令也不能直接替代这些条件。原文未说明匠石目前技能是否衰退，不需补成全部技艺仍完全不变。"},{text:"吾无以为质矣，吾无与言之矣！",tone:"哀悼",guide:"由失去技艺对象转到失去交谈者，表达惠子之于庄子的特殊位置。可以理解为失去能相对而谈的人，不必断言二人终身全部言论都相互反对，也不必认定只有观点完全一致才算相知。"}]}),n[30]||(n[30]=t("",23)),a(s,{sections:P,glossary:j,"default-mode":"classic","aria-label":"徐无鬼·管仲荐隰朋 原文"}),n[31]||(n[31]=e("blockquote",null,[e("p",null,"**阅读说明：**管仲称鲍叔牙「洁廉，善士」，同时认为其处身方式不宜托国。两者应同时保留。"),e("p",null,"「上忘而下畔」「以德分人」「勿已」的具体训释有空间，不把谦下改成必然获所有人认可的管理公式。")],-1)),n[32]||(n[32]=e("h3",{id:"生僻字词-7",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"仲父",pinyin:["zhòng","fǔ"],meaning:"桓公对管仲的尊称。"},{term:"属",pinyin:["zhǔ"],meaning:"托付，恶乎属国之属读 zhǔ。"},{term:"比",pinyin:["bǐ"],meaning:"亲近、相与。"},{term:"钩",pinyin:["gōu"],meaning:"牵制、拘束等。"},{term:"隰朋",pinyin:["xí","péng"],meaning:"齐国人物，本段所荐之人。"},{term:"畔",pinyin:["pàn"],meaning:"本句有不同训释，不只作叛逆解。"},{term:"临人",pinyin:["lín","rén"],meaning:"居高临于他人。"},{term:"下人",pinyin:["xià","rén"],meaning:"谦下于他人，不作仆役名词解。"}]}),n[33]||(n[33]=e("h3",{id:"核心句引读-7",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"清廉应被肯定，容人和托付条件也需要辨明",subtitle:"有贤能，不必把贤能变成压在别人之上的身份。",lines:[{text:"其为人洁廉，善士也。",tone:"肯定",guide:"原文明确承认清廉与善，不可为了讲不执著就删去这一肯定。后文的不宜任用有具体理由，不能推成太清廉必然不能容人，更不能据此为贪腐或不守原则辩护。"},{text:"于不己若者不比之；一闻人之过，终身不忘。",tone:"处身",guide:"不与不如自己者相与，长期固定地记住他人之过，说明个体评价方式可能不适合广泛共同治理。闻过不忘不只等于记仇；反省的是能否允许改正、差异与重新相处。"},{text:"上且钩乎君，下且逆乎民。",tone:"任用后果",guide:"描述任用后可能造成的上下抵牾，不意味着君主不应受约束、百姓的任何意见都应接受。治理仍需原则、劝谏与保护，不能把不制造摩擦当作唯一任用标准。"},{text:"愧不若黄帝，而哀不己若者。",tone:"上下两面",guide:"能见自身不足，也能体察不及自身者，与只排斥不如己者形成对比。哀不必转为居高怜悯，可以联系不以能力差异否定他人；同时也不能让同情替代责任判断。"},{text:"以德分人谓之圣；以财分人谓之贤。",tone:"分享",guide:"本段仍肯定圣、贤及分享惠益，修正一切贤德都应排除的概括。分的具体解释需依注本处理，但不必将德设成可分装的物质。财的分享也说明本篇不只有抽象内心修养。"},{text:"以贤临人，未有得人者也；以贤下人，未有不得人者也。",tone:"贤与谦下",guide:"同样有贤能，临人与下人的方式却不同，批评的重点落在关系而非能力本身。绝对句式表达理想方向，现实中谦下并不保证人人服从；也不应把谦下用作获得服从的表演技巧。"},{text:"其于国有不闻也，其于家有不见也。",tone:"不苛察",guide:"可以联系不将每件小事都纳入苛察、保留相处余地理解。不能据此对伤害、违法与风险故意不见，不苛察与必要监督应区分。"},{text:"勿已则隰朋可。",tone:"托付",guide:"若必须有所托付，则提出隰朋这一选择。可与《庚桑楚》不得已对读，但不必认为任何推荐都应不热情、无计划。这里的回答已经包含对人物与任用后果的考量。"}]}),n[34]||(n[34]=t("",33)),a(s,{sections:T,glossary:v,"default-mode":"classic","aria-label":"徐无鬼·吴王射狙 原文"}),n[35]||(n[35]=e("blockquote",null,[e("p",null,"**阅读说明：**猴之死先有射杀情节，随后才有吴王对死因的解释。两者不能合并成受害者应负全部责任的结论。"),e("p",null,"「攫𢮞」「相者」「趋」「执死」等保留校释空间；「见巧」的见联系现理解。")],-1)),n[36]||(n[36]=e("h3",{id:"生僻字词-8",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"狙",pinyin:["jū"],meaning:"猴类。"},{term:"恂然",pinyin:["xún","rán"],meaning:"惊惧之状。"},{term:"蓁",pinyin:["zhēn"],meaning:"草木丛生之处。"},{term:"委蛇",pinyin:["wēi","yí"],meaning:"活动从容等，依本段语境理解。"},{term:"敏给",pinyin:["mǐn","jǐ"],meaning:"敏捷。"},{term:"伐其巧",pinyin:["fá","qí","qiǎo"],meaning:"夸耀、自负其技巧。"},{term:"殛",pinyin:["jí"],meaning:"杀死、诛杀。"},{term:"锄其色",pinyin:["chú","qí","sè"],meaning:"去除骄矜外显之态。"}]}),n[37]||(n[37]=e("h3",{id:"核心句引读-8",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"技巧不等于能够掌握处境，戒骄也不替代对暴力的判断",subtitle:"区分行为、人物解释与现代引申。",lines:[{text:"王射之，敏给搏捷矢。王命相者趋射之，狙执死。",tone:"处境",guide:"一次能应付来矢，不等于能够承受被加大的攻击。故事显示技巧有条件与限度，而王能调动更多射者，双方力量并不对等。不能只留下猴的自负而删去实施射杀的权力。"},{text:"伐其巧、恃其便以敖予，以至此殛也。",tone:"王之言",guide:"这是吴王对猴之死的解释，含有以不敬自己说明杀戮的意味。可以据此读戒骄，也应辨明它并非自动等于作者已认可王的全部判断。展示能力与应受暴力之间没有必然正当关系。"},{text:"无以汝色骄人哉？",tone:"骄人",guide:"对颜不疑的告诫落在骄人，而不只是有没有外显才能。表现能力、说明贡献不必就是傲慢；问题在如何凭所长对待他人，以及是否误把能力当成掌握全部处境的保证。"},{text:"以锄其色，去乐辞显。",tone:"修整",guide:"去除骄矜、辞去显达等构成颜不疑的转变。不能将色只定为才能，进而要求抹去全部技能；也不能把辞显当作每个人的唯一生活道路。"},{text:"三年而国人称之。",tone:"名声",guide:"不以骄态显于人，却仍获得称赞，说明外界评价未必能由自己取消。不能读成收敛三年必然得名，也不必倒推此前修整只是为了更高的名声。"}]}),n[38]||(n[38]=t("",8)),a(s,{sections:A,glossary:S,"default-mode":"classic","aria-label":"徐无鬼·南伯子綦与悲的反省 原文"}),n[39]||(n[39]=e("blockquote",null,[e("p",null,"**出处说明：**本段可与《齐物论》开头对读，但《齐物论》是全书第二篇，《徐无鬼》属于杂篇。"),e("p",null,"「我必先之」「我必卖之」「其后而日远」存在解释空间，不将自省改写为一切侵害都由自己造成。")],-1)),n[40]||(n[40]=e("h3",{id:"生僻字词-9",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"子綦",pinyin:["zǐ","qí"],meaning:"本段人物。"},{term:"隐几",pinyin:["yǐn","jī"],meaning:"倚靠几案。"},{term:"嘘",pinyin:["xū"],meaning:"呼气、长叹。"},{term:"槁骸",pinyin:["gǎo","hái"],meaning:"枯槁形骸的譬喻。"},{term:"鬻",pinyin:["yù"],meaning:"卖。"},{term:"自丧",pinyin:["zì","sàng"],meaning:"自身丧失、失其自身。"}]}),n[41]||(n[41]=e("h3",{id:"核心句引读-9",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"回看自己如何参与显名，不等于替他人的利用免责",subtitle:"悲可以受到反省，关怀却不必因此被取消。",lines:[{text:"形固可使若槁骸，心固可使若死灰乎？",tone:"形与心",guide:"形心的反常状态以问句呈现，不是直接列出得道者必须具备的外观。可与《齐物论》相近场景对读，但不能要求现实中的人失去感受、呈现枯槁才算通达。"},{text:"田禾一睹我而齐国之众三贺之。",tone:"显名",guide:"相见被众人赋予价值，提示隐处也未必脱离声誉关系。原文没有明说田禾因此得到重用，不补写这一政治结果。可以关注一场相见如何被传播、评价或利用。"},{text:"我必卖之，彼故鬻之。",tone:"自省",guide:"子綦把目光转回自身如何参与名声的显露，这是自省的重要方向。但显露与被他人利用不是同一行为，检查自己的参与不等于他人利用便合理，更不等于所有受害都由受害者造成。"},{text:"我悲人之自丧者；吾又悲夫悲人者。",tone:"回看悲",guide:"由悲他人到回看悲人者，打断只把问题放在别人身上的姿态。可以反省自居洞见者、反复评判等倾向，却不能直接把悲悯等同傲慢。体察处境、提供支持也可以是不居高的关怀。"},{text:"吾又悲夫悲人之悲者；其后而日远矣！",tone:"递归",guide:"对悲的反省仍可能继续成为新的悲与评判，形成递归。所远为何及句法仍有讨论空间，不宜把它变成三层修养等级。也不证明只要停止关怀别人便自然接近道。"}]}),n[42]||(n[42]=t("",16)),a(s,{sections:C,glossary:V,"default-mode":"classic","aria-label":"徐无鬼·不言之辩与大人 原文"}),n[43]||(n[43]=e("blockquote",null,[e("p",null,"**阅读说明：**本段聚集多种反常表达。弄丸解难、甘寝投兵按寓言理解，不保证现实争端可由杂技或睡眠自动解决。"),e("p",null,"开头「爵」是酒器，后文「生无爵」的爵是爵位；两处不能统一作同一义。")],-1)),n[44]||(n[44]=e("h3",{id:"生僻字词-10",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"觞",pinyin:["shāng"],meaning:"以酒款待。"},{term:"爵",pinyin:["jué"],meaning:"前文为酒器，后文为爵位。"},{term:"弄丸",pinyin:["nòng","wán"],meaning:"操作丸球等技艺。"},{term:"喙",pinyin:["huì"],meaning:"嘴。"},{term:"休",pinyin:["xiū"],meaning:"止息。"},{term:"谥",pinyin:["shì"],meaning:"死后的称号。"},{term:"大备",pinyin:["dà","bèi"],meaning:"广大完备。"},{term:"易己",pinyin:["yì","jǐ"],meaning:"交换、换失自身等。"},{term:"摩",pinyin:["mó"],meaning:"磨损等。"}]}),n[45]||(n[45]=e("h3",{id:"核心句引读-10",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"言说有边界，但相处的效果不只由言说多少决定",subtitle:"大不只靠名位、善言与积聚来证明。",lines:[{text:"市南宜僚弄丸而两家之难解。",tone:"解难",guide:"以弄丸解难突出不按常规辩说争胜的效果。原文未详述争端经过，不能补成此前无人沟通、没有其他条件，只要玩丸便自动和解。可以关注实际作用不只来自口头说服。"},{text:"孙叔敖甘寝秉羽而郢人投兵。",tone:"投兵",guide:"安卧持羽与投兵相接，是理想化的安定意象。不证明人物什么都没做，也不保证现实停战无需协商、保护与制度安排。无强作不等于毫无背景条件。"},{text:"彼之谓不道之道，此之谓不言之辩。",tone:"反常表达",guide:"道可含言说义，不道之道、不言之辩限制通常说辩形式的充分性。本段仍在言说这些问题，因此不能整理成只要开口就离道、沉默自动是真理。"},{text:"言休乎知之所不知，至矣。",tone:"知限",guide:"在所知无法穷尽处不强立说，提醒承认说明范围。不是把所有当前未知宣布成永远不可研究，也不要求面对具体问题拒绝解释。可以继续求证，并诚实标明不确定性。"},{text:"道之所一者，德不能同也。",tone:"一与同",guide:"道之所一与德不能同相接，说明一、同不宜直接混用。可联系道的贯通不能由某一德的表现穷尽理解，也有其他训释。不能只据此建立每人德表现不同但都已得道的普遍结论。"},{text:"海不辞东流，大之至也。",tone:"容纳",guide:"以海容受来水说明大，不仅以排斥、划界维持自己。现代可联系容纳差异，却不能因此要求没有边界、接受所有侵害。容纳与必要保护不是反义词。"},{text:"生无爵，死无谥，实不聚，名不立。",tone:"名与实",guide:"以不聚不立限制外在占有和称号对大的证明。不能按资产、职位清单裁定人格，也不要求为修养主动陷入匮乏。前文仍肯定分财与泽及天下，资源可以被使用与分享。"},{text:"人不以善言为贤，而况为大乎！",tone:"善言",guide:"善言不足以单独证明贤、大，不等于说话清楚、善于沟通毫无价值。与第七段无与言者对读，言说的价值与言说不能穷尽人的价值，可以同时成立。"},{text:"不以物易己也。反己而不穷。",tone:"反己",guide:"不以外物换失自身，可以联系不把生命完全质押给名利要求。返回自身不等于拒绝所有反馈、帮助与学习，也不保证存在一个永远不应改变的自我。"},{text:"循古而不摩，大人之诚！",tone:"诚",guide:"循古与不磨损的关系有解释空间，不必作机械复古。与第二段修胸中之诚对读，可保留真实处身与不侵扰的方向，而不是以自称真诚免除实际行为检验。"}]}),n[46]||(n[46]=t("",19)),a(s,{sections:I,glossary:D,"default-mode":"classic","aria-label":"徐无鬼·子綦相子与祥的代价 原文"}),n[47]||(n[47]=e("blockquote",null,[e("p",null,[e("strong",null,"文字说明："),i("「九方囗」按上下文统一为「九方歅」。「渠公之街」「然身」等保留来稿字形，最终依项目底本校定。")]),e("p",null,"预言与结局的呼应属于寓言安排，不验证现实相术；盗贼造成的侵害也不能归为梱的过错。")],-1)),n[48]||(n[48]=e("h3",{id:"生僻字词-11",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-11","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"九方歅",pinyin:["jiǔ","fāng","yīn"],meaning:"篇中的相者。"},{term:"梱",pinyin:["kǔn"],meaning:"子綦之子，保留来稿字形。"},{term:"瞿然",pinyin:["jù","rán"],meaning:"惊动、惊喜之状。"},{term:"涕",pinyin:["tì"],meaning:"眼泪。"},{term:"牂",pinyin:["zāng"],meaning:"母羊。"},{term:"奥",pinyin:["ào"],meaning:"室内深处、角落等。"},{term:"宎",pinyin:["yǎo"],meaning:"室内处所的疑难用语。"},{term:"刖",pinyin:["yuè"],meaning:"砍去足部。"},{term:"鬻",pinyin:["yù"],meaning:"卖。"}]}),n[49]||(n[49]=e("h3",{id:"核心句引读-11",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-11","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"不能只看获得什么，还要问怎样获得、付出什么",subtitle:"吉祥判断不能遮住生命与身体的代价。",lines:[{text:"将与国君同食以终其身。",tone:"祥的尺度",guide:"九方歅以同食终身为祥，预设亲近权位、衣食优厚即可证明福。子綦转而落泪，打断这一尺度。不能立即补成梱已经主动追求富贵，原文此时只有相者的判断。"},{text:"今夫子闻之而泣，是御福也。",tone:"相者之言",guide:"哭泣被九方歅解释成阻挡福，是人物评价，不是作者为现实运势规定机制。悲伤不会仅因存在就证明父亲不祥，更不能以此禁止表达担忧。"},{text:"何足以知其所自来！",tone:"来源",guide:"不只看酒肉进入鼻口，还追问这一结果怎样来到。结尾的暴力与出售使来源问题格外沉重。现代可检查利益来源与代价，但不据此说所有优厚待遇都必定有害。"},{text:"乘天地之诚而不以物与之相撄。",tone:"父子关系",guide:"描述相与生活而不以外物要求纠缠对方。不能把它宣布为唯一真正的父子关系，也不能要求父母不教育、不安排、不保护。可以反省是否将孩子质押给世俗成就。"},{text:"非我与吾子之罪，几天与之也！",tone:"非罪",guide:"原文明说不是父子之罪，不能反译为梱已经离道所以招灾。天可联系不能完全控制的际遇，仍不免除随后盗贼实施暴力的责任。"},{text:"全而鬻之则难，不若刖之则易。",tone:"侵害",guide:"盗贼为出售便利损毁身体，揭露以交易用途衡量人的残酷。不能整理成梱以刖足换取富贵的自愿选择；他是遭劫、受伤和被出售的一方。"},{text:"然身食肉而终。",tone:"结局",guide:"末句与前面的食终身形成反转，但并未重复与国君同席。街、然身尚需校读，不把结局扩写成所有预言细节已精准应验，更不称这样的结局足以证明幸福。"}]}),n[50]||(n[50]=t("",15)),a(s,{sections:R,glossary:G,"default-mode":"classic","aria-label":"徐无鬼·许由逃尧与仁义工具化 原文"}),n[51]||(n[51]=e("blockquote",null,[e("p",null,"**阅读说明：**本段对尧与仁义的批评十分激烈，不将其弱化成普通的谨慎建议。"),e("p",null,"同时区分人物的警告、工具化的分析与现代事实判断；「覕」「捐」「禽贪」的细义待统一底本校定。")],-1)),n[52]||(n[52]=e("h3",{id:"生僻字词-12",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-12","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"啮缺",pinyin:["niè","quē"],meaning:"篇中问话者。"},{term:"许由",pinyin:["xǔ","yóu"],meaning:"篇中答话者，亦见相关古代传说。"},{term:"畜畜然",pinyin:["chù","chù","rán"],meaning:"殷勤、勤谨等，音义依注本统一。"},{term:"劝",pinyin:["quàn"],meaning:"受到激励、勤勉。"},{term:"捐",pinyin:["juān"],meaning:"舍、弃等，有不同训释。"},{term:"假",pinyin:["jiǎ"],meaning:"借、借用。"},{term:"覕",pinyin:["piē"],meaning:"短见、片刻之见等，音义待校。"},{term:"贼",pinyin:["zéi"],meaning:"损害，不只指盗贼。"}]}),n[53]||(n[53]=e("h3",{id:"核心句引读-12",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-12","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"仁义之名不能保证无害，贤人之利也不能遮住其可能之害",subtitle:"质疑道德权威的充分性，不等于取消实际关怀。",lines:[{text:"夫尧畜畜然仁……后世其人与人相食与！",tone:"激烈警告",guide:"对通常被肯定的圣王行仁提出极端后果警告，力度应保留。不能把它当作已证实的千世历史预测，也不能推出关怀一发生便必然造成灾难。需要结合后文利用仁义与一人断制的批评理解。"},{text:"爱之则亲，利之则至，誉之则劝。",tone:"聚人",guide:"爱、利、誉能使人亲附与受激励，提示政治动员不只靠真实德行。这是一种概括，并非对全部民众心理的完整说明，也不宜转为利用需求操纵他人的操作方法。"},{text:"利仁义者众。",tone:"利用",guide:"指出仁义可被作为获取利益的手段，名称与目的可能分离。众是论述中的概括，不能当作现代统计。可以检查名实，却不能只因某人自称仁义就认定其必然虚伪。"},{text:"唯且无诚，且假乎禽贪者器。",tone:"工具",guide:"仁义行为可能失其诚，被贪求者借为工具，这是本段鲜明批评。不能完全消解成只要本心真诚便无问题；第二段已经要求看是否苦民、杀民兼地，实际行为和后果仍须检查。"},{text:"一人之断制天下，譬之犹一覕也。",tone:"断制",guide:"以一人的判断断制天下，被比作短见、片面之见等。覕的具体训释有空间，但上下文清楚地反省单一权威。不能由此将任何共同规则、专业判断和组织安排都取消。"},{text:"知贤人之利天下也，而不知其贼天下也。",tone:"两面",guide:"只看贤者之利，却忽略可能之害，限制贤名自动保证正确的预设。它并未只留下害，也明确提及利；不能把贤者整体变成应排除的有害群体。"},{text:"夫唯外乎贤者知之矣。",tone:"不拘贤名",guide:"可以联系不受贤名的评价框架拘限，因而能看见其两面。不能另立超越贤者者天然全知的新等级，也不保证自称框架外就无需证据与反馈。"}]}),n[54]||(n[54]=t("",34)),a(s,{sections:N,glossary:E,"default-mode":"classic","aria-label":"徐无鬼·暖姝与濡需 原文"}),n[55]||(n[55]=e("blockquote",null,[e("p",null,"**整理说明：**来稿未在开头连续列出原文，本页依据所引句段重新排列，并补列三类名称的总起句。"),e("p",null,"「未知未始有物」不只等于没有学到任何东西；「卷娄」的说明实际接续在濡需之后，不能用善卷拒舜替换。")],-1)),n[56]||(n[56]=e("h3",{id:"生僻字词-13",tabindex:"-1"},[i("生僻字词 "),e("a",{class:"header-anchor",href:"#生僻字词-13","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(r,{items:[{term:"暖姝",pinyin:["nuǎn","shū"],meaning:"自得、自满之状。"},{term:"濡需",pinyin:["rú","xū"],meaning:"沾滞、依附等。"},{term:"卷娄",pinyin:["quán","lóu"],meaning:"本段第三类名称，后文以舜说明。"},{term:"私自说",pinyin:["sī","zì","yuè"],meaning:"私下自悦。"},{term:"豕虱",pinyin:["shǐ","shī"],meaning:"猪身上的虱子。"},{term:"鬣",pinyin:["liè"],meaning:"鬃毛。"},{term:"隈",pinyin:["wēi"],meaning:"曲折、弯曲之处。"},{term:"囿",pinyin:["yòu"],meaning:"园囿，也可联系圈限理解。"}]}),n[57]||(n[57]=e("h3",{id:"核心句引读-13",tabindex:"-1"},[i("核心句引读 "),e("a",{class:"header-anchor",href:"#核心句引读-13","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"学习的喜悦不必否定，自以为已经足够却需要检查",subtitle:"在同一范围内不断调整，不等于已经检查了范围本身。",lines:[{text:"学一先生之言，则暖暖姝姝而私自说也。",tone:"学习与自满",guide:"暖姝并非未曾学习，而是学一家之言便安于自悦。不能因此说学习只有自我安慰的作用，也不能把受益后的喜悦全部否定。需要反省的是是否还愿意面对其他观点与问题。"},{text:"自以为足矣，而未知未始有物也。",tone:"足的判断",guide:"自认已经足够，与未知未始有物形成对照。后半句涉及哲学意义与句法，不宜直接译成此前没有真正获得任何知识。可以先保留对自足判断的限制，不急于宣判所有所得为空。"},{text:"自以为广宫大囿……自以为安室利处。",tone:"所居与尺度",guide:"虱以猪体局部为广大安稳之所，显示评价受所依条件限制。不能据此认为任何局部生活都愚昧，也不要求掌握全部世界后才可生活。局部可以适用，却不是无条件的保证。"},{text:"而己与豕俱焦也。",tone:"共同风险",guide:"所依条件受到毁坏，局部位置的调整也难以保全虱。可以联系依赖风险，但不能把遭受共同灾害者都指责为苟且者。风险还涉及外部行为和无法完全控制的变化。"},{text:"此以域进，此以域退。",tone:"共享前提",guide:"看似有进有退，却仍在同一范围内。现代可以检查多个选项是否共享未经检验的前提，不必把所有有限选择判为无效。改变范围也需要现实条件，并非靠自称超越便能完成。"}]}),n[58]||(n[58]=t("",19)),a(s,{sections:B,glossary:F,"default-mode":"classic","aria-label":"徐无鬼·卷娄与真人 节引"}),n[59]||(n[59]=t("",63))])}}});export{W as __pageData,X as default};
